(window.MAP_DATA = window.MAP_DATA || {})["language_4"] = {"grade":4,"subject":"language","units":[{"id":"U1","title":"Organize Writing: Introductions, Transitions and Conclusions","goal":"WR","band":"161–190","skills":["Write an introduction that tells the topic","Link ideas with transitions such as for example, also and because","Group related information together","Write a conclusion that sums up the main idea"],"vocab":[["introduction","the beginning that tells the reader the topic"],["topic sentence","the sentence that states the main idea of a paragraph"],["transition","a word or phrase that links ideas, such as for example or in addition"],["supporting detail","a fact, example or reason that explains the main idea"],["paragraph","a group of sentences about one main idea"],["conclusion","the ending that sums up the main idea"]],"sets":[{"set":"A","passage":{"title":"Desert Foxes","genre":"draft","paras":["(1) The fennec fox is the smallest fox in the world. (2) It lives in the deserts of North Africa. (3) Its huge ears help it hear insects moving under the sand. (4) Its ears also help it stay cool on hot days. (5) My grandmother lives in Medina. (6) The fox has thick fur on its feet. (7) The fur protects its feet from the burning sand."],"intro":"Talal is writing a report about the fennec fox. Read his draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which sentence does NOT belong in the report?","o":["sentence 2","sentence 4","sentence 5","sentence 6"],"k":"C","sk":"Identifies a sentence that does not belong","b":"161–170","g":"WR"},{"n":2,"t":"mc","s":"Which phrase could BEST begin sentence 6 to show that a new detail is coming?","o":["As a result,","In the end,","For example,","In addition,"],"k":"D","sk":"Chooses a transition that connects ideas","b":"171–180","g":"WR"},{"n":3,"t":"mc","s":"Which sentence would make the MOST interesting introduction?","o":["Foxes are animals, and there are many of them.","Imagine a fox small enough to fit in your hands!","I am going to write about the fennec fox now.","This report is going to tell you about some foxes."],"k":"B","sk":"Chooses an effective introduction","b":"171–180","g":"WR"},{"n":4,"t":"mc","s":"Which is the BEST way to combine sentences 6 and 7?","o":["The fox has thick fur on its feet that protects them from the burning sand.","The fox has thick fur on its feet protects them from the burning sand.","The fox has thick fur on its feet, and protects, from the burning sand.","The fox has thick fur on its feet, the fur protects its feet from the hot sand."],"k":"A","sk":"Combines sentences correctly","b":"181–190","g":"GU"},{"n":5,"t":"mc","s":"Which sentence would be the BEST conclusion for the report?","o":["The fennec fox has many features that help it survive in the desert.","My grandmother has a lazy cat that sleeps on her bed every single afternoon.","The desert is a big place with lots of sand and a few plants.","Some foxes live in forests and others live in cold places."],"k":"A","sk":"Chooses an effective concluding sentence","b":"181–190","g":"WR"},{"n":6,"t":"mc","s":"Where is the BEST place to add this sentence?\n“It hunts at night, when the desert is cooler.”","o":["after sentence 7","after sentence 5","after sentence 3","before sentence 1"],"k":"C","sk":"Puts sentences or events in a logical order","b":"191–200","g":"WR"}]},{"set":"B","passage":{"title":"A Day at the Science Museum","genre":"draft","paras":["(1) Last Tuesday, our class visited the science museum. (2) We saw a model of the solar system that hung from the ceiling. (3) A guide showed us how electricity lights a bulb. (4) Then we touched a ball that made our hair stand up! (5) After lunch, we watched a movie about the ocean. (6) The museum has a gift shop. (7) It was the best trip of the year."],"intro":"Ruba wrote about her class trip. Read her draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which sentence is LEAST important to the story of the trip and could be removed?","o":["sentence 2","sentence 3","sentence 5","sentence 6"],"k":"D","sk":"Identifies a sentence that does not belong","b":"161–170","g":"WR"},{"n":2,"t":"mc","s":"Which word in sentence 4 helps show the order of events?","o":["Then","touched","hair","made"],"k":"A","sk":"Chooses a transition that connects ideas","b":"161–170","g":"WR"},{"n":3,"t":"mc","s":"Which sentence would BEST follow sentence 3 to explain what happened?","o":["Light bulbs come in many shapes and many sizes.","When he closed the switch, the bulb began to glow.","Electricity is used in homes all over the world.","My father changed a bulb in our kitchen last week."],"k":"B","sk":"Adds a detail that supports the main idea","b":"171–180","g":"WR"},{"n":4,"t":"mc","s":"Which word could replace “touched” in sentence 4 to be MORE exact?","o":["had","got","rubbed","did"],"k":"C","sk":"Chooses precise or vivid language","b":"171–180","g":"WR"},{"n":5,"t":"mc","s":"Which sentence would be a better ending that tells WHY it was the best trip?","o":["I learned more in one day than I expected, and it was all fun.","The museum is open every day except Friday and Saturday.","We rode the bus back to school at two o’clock in the afternoon.","Our teacher counted us three times before we left the museum."],"k":"A","sk":"Chooses an effective concluding sentence","b":"181–190","g":"WR"},{"n":6,"t":"mc","s":"Ruba wants to add a sentence that tells what she learned from the ocean movie. Which is BEST?","o":["My cousin has seen the same movie two times.","The ocean is very big, and it is very blue.","The movie was in a dark room with big seats.","I learned that some fish make their own light."],"k":"D","sk":"Adds a detail that supports the main idea","b":"181–190","g":"WR"},{"n":7,"t":"mc","s":"Which phrase could BEST begin sentence 2?","o":["However,","In conclusion,","First,","For this reason,"],"k":"C","sk":"Chooses a transition that connects ideas","b":"181–190","g":"WR"}]}]},{"id":"U2","title":"Develop Writing: Details, Precise Words, Dialogue and Research","goal":"WR","band":"171–200","skills":["Develop a topic with facts, definitions and examples","Use precise and concrete words","Use dialogue and description in stories","Take notes and choose reliable sources"],"vocab":[["fact","information that can be checked and proved"],["example","a specific case that shows what you mean"],["precise word","a word that says exactly what you mean"],["dialogue","the words that characters say to each other"],["source","where information comes from: a book, website or expert"],["formal language","careful language used in reports and letters to adults"]],"sets":[{"set":"A","passage":{"title":"The Broken Kite","genre":"draft","paras":["(1) Hadi ran to the top of the hill with his new kite. (2) The wind was strong. (3) The kite went up into the sky. (4) Suddenly, the string snapped. (5) The kite drifted away over the rooftops. (6) Hadi felt bad. (7) Then his older sister came running up the hill with her own kite."],"intro":"Jumana is writing a story. Read her draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which sentence could Jumana add after sentence 3 to help readers picture the kite?","o":["Kites were first made a very, very long time ago.","Hadi’s school is at the bottom of the hill.","Its long red tail danced and twisted in the wind.","The weather report said it would be windy."],"k":"C","sk":"Uses narrative techniques: dialogue, description and pacing","b":"171–180","g":"WR"},{"n":2,"t":"mc","s":"Which word could replace “went” in sentence 3 to be MORE exact?","o":["soared","got","moved","was"],"k":"A","sk":"Chooses precise or vivid language","b":"171–180","g":"WR"},{"n":3,"t":"mc","s":"Which revision of sentence 6 BEST shows how Hadi felt?","o":["Hadi was there, and the kite was not there anymore.","Hadi felt bad, and he felt bad for a long time after.","Hadi had a feeling about the kite and the string.","Hadi’s eyes filled with tears as the kite disappeared."],"k":"D","sk":"Chooses precise or vivid language","b":"181–190","g":"WR"},{"n":4,"t":"mc","s":"Which line of dialogue would BEST fit after sentence 7?","o":["“I like to eat dates and drink milk,” she said.","“Let’s fly mine together,” she said with a smile.","“Kites are made of paper and wood,” she said.","“What time is it right now?” she asked him."],"k":"B","sk":"Uses narrative techniques: dialogue, description and pacing","b":"181–190","g":"WR"},{"n":5,"t":"mc","s":"Which revision of sentence 2 adds the MOST helpful detail?","o":["The wind was strong on that day, I think, maybe.","The wind was strong, and it was also very windy.","The wind was strong enough to bend the palm trees.","The wind was a strong kind of wind for a while."],"k":"C","sk":"Adds a detail that supports the main idea","b":"181–190","g":"WR"},{"n":6,"t":"mc","s":"Which sentence would be the BEST ending for the story?","o":["Hadi ran to the top of the hill with his new kite.","Hadi smiled, and soon both of them were laughing in the wind.","The hill is near a road where many cars drive by.","Kites can be bought at most of the toy shops in every big city."],"k":"B","sk":"Chooses an effective concluding sentence","b":"191–200","g":"WR"}]},{"set":"B","passage":{"title":"Notes About Date Palms","genre":"draft","paras":["**Notes**","grow in hot, dry places · can live more than 100 years · one tree can give over 100 kg of dates a year · leaves are used to make baskets and mats","**Draft**","(1) Date palms are important trees in our country. (2) They grow well in hot, dry places. (3) They can live a long time. (4) People use almost every part of the tree. (5) The leaves are woven into baskets and mats. (6) Date palms are really cool trees."],"intro":"Saleh took notes for a report about date palm trees. Read his notes and his draft, then answer the questions."},"items":[{"n":1,"t":"mc","s":"Which revision of sentence 3 uses the notes to give an exact fact?","o":["They can live longer than most people think.","They can live for a really, really long time.","They can live a long time if you are lucky.","They can live for more than 100 years."],"k":"D","sk":"Uses notes and facts accurately in writing","b":"171–180","g":"WR"},{"n":2,"t":"mc","s":"Which phrase BEST begins sentence 5?","o":["However,","For example,","In conclusion,","Before that,"],"k":"B","sk":"Chooses a transition that connects ideas","b":"171–180","g":"WR"},{"n":3,"t":"mc","s":"Which question would help Saleh write a new paragraph?","o":["Do my friends like dates more than figs?","Is today a good day to go to the park?","How do farmers take care of date palms?","What color is the cover of my notebook?"],"k":"C","sk":"Chooses a useful source or research question","b":"171–180","g":"WR"},{"n":4,"t":"mc","s":"Which sentence uses the notes correctly to add a new fact?","o":["One tree can produce more than 100 kilograms of dates a year.","One tree can produce more than 1,000 kilograms of dates a day.","One tree can produce more than 100 baskets and mats every year.","One tree can produce dates for more than 100 different countries."],"k":"A","sk":"Uses notes and facts accurately in writing","b":"181–190","g":"WR"},{"n":5,"t":"mc","s":"Sentence 6 does not fit a report. Which sentence is BEST to replace it?","o":["Date palms are the best, and everyone knows that for sure.","For these reasons, date palms are super awesome, right?","I really love date palms more than anything in the world.","For these reasons, date palms are valuable to many families."],"k":"D","sk":"Keeps a consistent formal style and objective tone","b":"181–190","g":"WR"},{"n":6,"t":"mc","s":"Which source would be the MOST reliable for more facts about date palms?","o":["a blog post by a person who likes dates","a social media post with no author","a government website about farming","a cartoon about a talking palm tree"],"k":"C","sk":"Chooses a useful source or research question","b":"181–190","g":"WR"},{"n":7,"t":"mc","s":"Who is the BEST audience for this report?","o":["a doctor who works long hours in a big city hospital","classmates learning about plants of our country","a pilot who flies airplanes overseas","a chef looking for a cake recipe"],"k":"B","sk":"Chooses language that fits the purpose and audience","b":"191–200","g":"WR"}]}]},{"id":"U3","title":"Pronouns, Verbs and Modifiers","goal":"GU","band":"161–200","skills":["Use relative pronouns: who, whose, whom, which, that","Use progressive verb tenses (was running, is running, will be running)","Use modal verbs: can, may, must, should","Order adjectives and use prepositional phrases"],"vocab":[["relative pronoun","a pronoun that connects a clause to a noun: who, whose, which, that"],["progressive tense","a verb form that shows continuing action: is reading, was reading"],["modal verb","a helping verb such as can, may, must or should"],["preposition","a word that shows place or time: in, on, under, after"],["prepositional phrase","a group of words that begins with a preposition: under the table"],["adjective order","the usual order of describing words: a small old blue box"]],"sets":[{"set":"A","passage":null,"items":[{"n":1,"t":"mc","s":"Which word correctly completes the sentence?\n“The girl ___ won the race is my cousin.”","o":["whose","which","what","who"],"k":"D","sk":"Uses relative pronouns and relative adverbs","b":"161–170","g":"GU"},{"n":2,"t":"mc","s":"Which words correctly complete the sentence?\n“At eight o’clock last night, I ___ my homework.”","o":["was doing","am doing","were doing","will be doing"],"k":"A","sk":"Uses progressive verb tenses","b":"171–180","g":"GU"},{"n":3,"t":"mc","s":"Which word BEST completes the sentence?\n“You ___ wear a helmet when you ride a bike. It is the rule.”","o":["could","must","might","may"],"k":"B","sk":"Uses modal auxiliaries","b":"171–180","g":"GU"},{"n":4,"t":"mc","s":"Which sentence lists the adjectives in the correct order?","o":["She has a little white lovely cat.","She has a white lovely little cat.","She has a lovely little white cat.","She has a white little lovely cat."],"k":"C","sk":"Uses adjectives and adverbs correctly, including comparisons","b":"181–190","g":"GU"},{"n":5,"t":"mc","s":"Which part of the sentence is a prepositional phrase?\n“The keys were hidden under the old blanket.”","o":["hidden","under the old blanket","The keys were","The keys were hidden"],"k":"B","sk":"Uses prepositions and prepositional phrases","b":"181–190","g":"GU"},{"n":6,"t":"mc","s":"Which word correctly completes the sentence?\n“The man ___ car was stolen called the police.”","o":["whose","whom","which","who"],"k":"A","sk":"Uses relative pronouns and relative adverbs","b":"191–200","g":"GU"}]},{"set":"B","passage":{"title":"My Neighbor the Baker","genre":"draft","paras":["(1) Mr. Nabil is a baker which lives next door to us. (2) Every morning, he is baking bread before the sun comes up. (3) Yesterday, while I was walk to school, he waved at me. (4) He gave me a round little delicious roll. (5) His bakery is famous among our street. (6) People say you can smell the bread from three blocks away. (7) Someday I might will learn to bake like him."],"intro":"Yazeed wrote about his neighbor. His draft has some mistakes. Read it and answer the questions."},"items":[{"n":1,"t":"mc","s":"What is the correct way to write sentence 1?","o":["Mr. Nabil is a baker who lives next door to us.","Mr. Nabil is a baker what lives next door to us.","Mr. Nabil is a baker whose lives next door to us.","Mr. Nabil is a baker whom lives next door to us."],"k":"A","sk":"Uses relative pronouns and relative adverbs","b":"171–180","g":"GU"},{"n":2,"t":"mc","s":"Which word should replace “walk” in sentence 3?","o":["walked","walking","walker","walks"],"k":"B","sk":"Uses progressive verb tenses","b":"171–180","g":"GU"},{"n":3,"t":"mc","s":"Which word should replace “among” in sentence 5?","o":["between","across","beside","on"],"k":"D","sk":"Uses prepositions and prepositional phrases","b":"181–190","g":"GU"},{"n":4,"t":"mc","s":"What is the correct way to write sentence 7?","o":["Someday I might will learn to bake like him.","Someday I might learned to bake like him.","Someday I might learn to bake like him.","Someday I might learning to bake like him."],"k":"C","sk":"Uses modal auxiliaries","b":"181–190","g":"GU"},{"n":5,"t":"mc","s":"What is the correct way to write sentence 2?","o":["Every morning, he have baked bread before the sun comes up.","Every morning, he bakes bread before the sun comes up.","Every morning, he baking bread before the sun comes up.","Every morning, he were baking bread before the sun comes up."],"k":"B","sk":"Uses verb tenses correctly","b":"181–190","g":"GU"},{"n":6,"t":"mc","s":"In sentence 6, which phrase tells WHERE?","o":["People say you can smell","the bread","People say","from three blocks away"],"k":"D","sk":"Uses prepositions and prepositional phrases","b":"181–190","g":"GU"},{"n":7,"t":"mc","s":"Which is the correct way to write “a round little delicious roll” in sentence 4?","o":["a delicious little round roll","a round delicious little roll","a little round delicious roll","a little delicious round roll"],"k":"A","sk":"Uses adjectives and adverbs correctly, including comparisons","b":"191–200","g":"GU"}]}]},{"id":"U4","title":"Complete Sentences, Agreement and Confused Words","goal":"GU","band":"171–200","skills":["Fix fragments and run-on sentences","Make subjects and verbs agree, even with phrases in between","Choose between to, too, two; there, their, they’re; its, it’s","Combine sentences with and, but, or, so"],"vocab":[["fragment","a group of words that is not a complete sentence"],["run-on sentence","two sentences joined without correct punctuation or a joining word"],["subject-verb agreement","a singular subject takes a singular verb; a plural subject takes a plural verb"],["homophones","words that sound the same but have different meanings and spellings"],["compound sentence","two complete sentences joined by a comma and and, but, or or so"],["complete subject","all the words that tell who or what the sentence is about"]],"sets":[{"set":"A","passage":null,"items":[{"n":1,"t":"mc","s":"Which word correctly completes the sentence?\n“We were ___ tired to finish the game.”","o":["too","tow","to","two"],"k":"A","sk":"Chooses between frequently confused words","b":"171–180","g":"GU"},{"n":2,"t":"mc","s":"Which sentence is a run-on?","o":["We went outside after the rain stopped.","When the rain stopped, we went outside.","The rain stopped, so we went outside.","The rain stopped we went outside to play."],"k":"D","sk":"Recognizes complete sentences, fragments and run-ons","b":"171–180","g":"GU"},{"n":3,"t":"mc","s":"Which word correctly completes the sentence?\n“The students left ___ backpacks in the hall.”","o":["there","their","thier","they’re"],"k":"B","sk":"Chooses between frequently confused words","b":"171–180","g":"GU"},{"n":4,"t":"mc","s":"Which word correctly completes the sentence?\n“The box of crayons ___ on the shelf.”","o":["are","were","is","be"],"k":"C","sk":"Makes subjects and verbs agree","b":"181–190","g":"GU"},{"n":5,"t":"mc","s":"Which is the BEST way to combine the sentences?\n“Lina wanted to swim. The pool was closed.”","o":["Lina wanted to swim so the pool was closed.","Lina wanted to swim, the pool was closed.","Lina wanted to swim, but the pool was closed.","Lina wanted to swim but the pool, was closed."],"k":"C","sk":"Combines sentences correctly","b":"181–190","g":"GU"},{"n":6,"t":"mc","s":"Which word correctly completes the sentence?\n“Neither of my brothers ___ coffee.”","o":["like","are liking","were liking","likes"],"k":"D","sk":"Makes subjects and verbs agree","b":"201–210","g":"GU"}]},{"set":"B","passage":{"title":"The School Play","genre":"draft","paras":["(1) Our class is putting on a play about the history of Taif. (2) Every student in the classes have a part. (3) I am playing a merchant who sells perfume. (4) Practicing every day after lunch. (5) My lines are long, I practice them at home. (6) My parents and my little sister is coming to watch. (7) I hope I remember all my lines, I don’t want to forget any of them. (8) Its going to be a great night."],"intro":"Khalid wrote about his school play. His draft has some mistakes. Read it and answer the questions."},"items":[{"n":1,"t":"mc","s":"Sentence 4 is a fragment. Which is the BEST way to fix it?","o":["We are practicing every day after lunch.","Every day practicing after lunch.","After lunch practicing every day.","Practicing every single day, after lunch."],"k":"A","sk":"Recognizes complete sentences, fragments and run-ons","b":"171–180","g":"GU"},{"n":2,"t":"mc","s":"What is the correct way to write sentence 2?","o":["Every student in the classes are having a part.","Every student in the classes has a part.","Every student in the classes having a part.","Every students in the classes have a part."],"k":"B","sk":"Makes subjects and verbs agree","b":"181–190","g":"GU"},{"n":3,"t":"mc","s":"What is the correct way to write sentence 5?","o":["My lines are long, I practice them, at home.","My lines are long so, I practice them at home.","My lines are long I practice them at home.","My lines are long, so I practice them at home."],"k":"D","sk":"Recognizes complete sentences, fragments and run-ons","b":"181–190","g":"GU"},{"n":4,"t":"mc","s":"Which word should replace “is” in sentence 6?","o":["be","been","are","was"],"k":"C","sk":"Makes subjects and verbs agree","b":"181–190","g":"GU"},{"n":5,"t":"mc","s":"Which word should replace “Its” in sentence 8?","o":["It","It’s","Is","Its’"],"k":"B","sk":"Chooses between frequently confused words","b":"181–190","g":"GU"},{"n":6,"t":"mc","s":"Sentence 7 is a run-on. Which is the BEST way to fix it?","o":["I hope I remember all my lines and, I don’t want to forget them.","I hope I remember all my lines I don’t want to forget any of them.","I hope I remember, all my lines, I don’t want to forget any of them.","I hope I remember all my lines because I don’t want to forget any."],"k":"D","sk":"Recognizes complete sentences, fragments and run-ons","b":"191–200","g":"GU"},{"n":7,"t":"mc","s":"Which is the BEST way to combine these sentences?\n“I am playing a merchant. The merchant sells perfume.”","o":["I am playing a merchant, sells perfume.","I am playing who sells a merchant perfume.","I am playing a merchant who sells perfume.","I am playing a merchant the merchant sells perfume."],"k":"C","sk":"Combines sentences correctly","b":"191–200","g":"GU"}]}]},{"id":"U5","title":"Capitalization and Commas","goal":"ME","band":"161–200","skills":["Capitalize titles, holidays, places, organizations and historical events","Use commas in compound sentences","Use commas after yes, no, well and introductory words","Use commas to set off the name of a person being spoken to"],"vocab":[["proper noun","the name of a specific person, place, thing or event"],["compound sentence","two complete sentences joined by a comma and a conjunction"],["introductory word","a word such as yes, no or well at the start of a sentence"],["direct address","speaking to someone by name: “Sami, come here.”"],["title","the name of a book, movie, song or article"],["abbreviation","a short form of a word, such as Dr. or Mr."]],"sets":[{"set":"A","passage":null,"items":[{"n":1,"t":"mc","s":"Which sentence is written correctly?","o":["We read about the Red sea in our science book.","We read about the red sea in our Science book.","We read about the Red Sea in our science book.","We read about the red Sea in our Science Book."],"k":"C","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"161–170","g":"ME"},{"n":2,"t":"mc","s":"Which sentence uses a comma correctly?","o":["Yes I would like, some more water.","Yes I would like some more, water.","Yes I would, like some more water.","Yes, I would like some more water."],"k":"D","sk":"Uses a comma after an introductory word, phrase or clause","b":"171–180","g":"ME"},{"n":3,"t":"mc","s":"Which sentence uses commas correctly?","o":["Sami, please hand me the scissors.","Sami please hand me, the scissors.","Sami please, hand me the scissors.","Sami please hand, me the scissors."],"k":"A","sk":"Uses a comma after an introductory word, phrase or clause","b":"171–180","g":"ME"},{"n":4,"t":"mc","s":"Which sentence uses a comma correctly?","o":["The movie, was long but it was exciting.","The movie was long, but it was exciting.","The movie was, long but it was exciting.","The movie was long but, it was exciting."],"k":"B","sk":"Uses a comma before a conjunction in a compound sentence","b":"181–190","g":"ME"},{"n":5,"t":"mc","s":"Which title is capitalized correctly?","o":["the Boy Who Lived In the Lighthouse","The boy who lived in the lighthouse","The Boy Who Lived in the Lighthouse","The Boy who Lived In The Lighthouse"],"k":"C","sk":"Capitalizes and punctuates titles of works","b":"191–200","g":"ME"},{"n":6,"t":"mc","s":"Which sentence is written correctly?","o":["My dad works for the Saudi red Crescent authority.","My Dad works for the Saudi Red crescent Authority.","My dad works for the saudi red crescent authority.","My dad works for the Saudi Red Crescent Authority."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"191–200","g":"ME"}]},{"set":"B","passage":{"title":"A Visit to Al-Ula","genre":"draft","paras":["(1) Last december, my family drove to Al-Ula. (2) We saw huge rocks shaped like animals and we visited old tombs carved into the mountains. (3) Our guide said “These tombs are about two thousand years old.” (4) Well I could not believe how old they were. (5) At night we looked at the stars from the desert. (6) My brother asked “Mom, can we come back next year?” (7) mom smiled and said that we would."],"intro":"Ghada wrote about a family trip. Her draft has some mistakes. Read it and answer the questions."},"items":[{"n":1,"t":"mc","s":"What is the correct way to write sentence 1?","o":["Last December, my family drove to Al-Ula.","Last december, my family drove to al-Ula.","Last December, my Family drove to Al-Ula.","last December, my family drove to Al-Ula."],"k":"A","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"161–170","g":"ME"},{"n":2,"t":"mc","s":"What is the correct way to write sentence 4?","o":["Well I could, not believe how old they were.","Well I could not believe, how old they were.","Well, I could not believe how old they were.","Well I could not believe how old, they were."],"k":"C","sk":"Uses a comma after an introductory word, phrase or clause","b":"171–180","g":"ME"},{"n":3,"t":"mc","s":"What is the correct way to write sentence 7?","o":["mom smiled and said that we would.","Mom Smiled and said that we would.","Mom smiled and said that We would.","Mom smiled and said that we would."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"171–180","g":"ME"},{"n":4,"t":"mc","s":"Where should a comma be added in sentence 2?","o":["after “visited”","after “animals”","after “huge”","after “mountains”"],"k":"B","sk":"Uses a comma before a conjunction in a compound sentence","b":"181–190","g":"ME"},{"n":5,"t":"mc","s":"What is the correct way to write sentence 3?","o":["Our guide said, “These tombs are about two thousand years old.”","Our guide said “These tombs are about two thousand years old”.","Our guide said, “These tombs are about two thousand years old”.","Our guide, said “These tombs are about two thousand years old.”"],"k":"A","sk":"Punctuates dialogue and quotations","b":"181–190","g":"ME"},{"n":6,"t":"mc","s":"Which sentence uses a comma correctly after an introductory phrase?","o":["At night we looked, at the stars from the desert.","At night, we looked at the stars from the desert.","At, night we looked at the stars from the desert.","At night we looked at the stars, from the desert."],"k":"B","sk":"Uses a comma after an introductory word, phrase or clause","b":"181–190","g":"ME"},{"n":7,"t":"mc","s":"What is the correct way to write sentence 6?","o":["My brother asked “Mom can we come back next year?”","My brother asked, “Mom can we come back, next year?”","My brother, asked “Mom, can we come back next year?”","My brother asked, “Mom, can we come back next year?”"],"k":"D","sk":"Punctuates dialogue and quotations","b":"191–200","g":"ME"}]}]},{"id":"U6","title":"Quotation Marks, Apostrophes and Spelling","goal":"ME","band":"171–200","skills":["Use quotation marks for dialogue and quotations from a text","Use apostrophes for singular and plural possessives","Spell words with suffixes correctly (-ful, -less, -ly, -ed, -ing)","Spell homophones and tricky words correctly"],"vocab":[["quotation marks","marks that show the exact words someone said or wrote"],["singular possessive","shows one owner: the boy’s bike"],["plural possessive","shows more than one owner: the boys’ bikes"],["suffix","a word ending that changes the meaning: care + ful = careful"],["homophone","a word that sounds like another word but is spelled differently: wait / weight"],["base word","a word that a prefix or suffix is added to"]],"sets":[{"set":"A","passage":null,"items":[{"n":1,"t":"mc","s":"Which word correctly completes the sentence?\n“She ___ the paper into a tiny square.”","o":["foldded","foldid","folded","fold"],"k":"C","sk":"Spells words with prefixes and suffixes correctly","b":"161–170","g":"ME"},{"n":2,"t":"mc","s":"Which word is spelled correctly?","o":["beautifull","beautiful","beautyful","beutiful"],"k":"B","sk":"Spells words with prefixes and suffixes correctly","b":"171–180","g":"ME"},{"n":3,"t":"mc","s":"Which word correctly completes the sentence?\n“The ___ of the box is ten kilograms.”","o":["weight","wait","weigth","waight"],"k":"A","sk":"Spells grade-level words correctly","b":"171–180","g":"ME"},{"n":4,"t":"mc","s":"The jackets belong to three girls. Which sentence is written correctly?","o":["The girls’s jackets are on the hooks.","The girl’s jackets are on the hooks.","The girls jackets are on the hooks.","The girls’ jackets are on the hooks."],"k":"D","sk":"Uses apostrophes in contractions and possessives","b":"181–190","g":"ME"},{"n":5,"t":"mc","s":"Which word is spelled correctly?","o":["library","libary","librery","liberry"],"k":"A","sk":"Spells grade-level words correctly","b":"181–190","g":"ME"},{"n":6,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Wait for me, “called Rami,” I am almost ready!","“Wait for me,” called Rami, “I am almost ready!”","“Wait for me” called Rami, “I am almost ready!”","“Wait for me,” called Rami “I am almost ready!”"],"k":"B","sk":"Punctuates dialogue and quotations","b":"191–200","g":"ME"}]},{"set":"B","passage":{"title":"The Winners","genre":"draft","paras":["(1) Our school held a poetry contest last week. (2) Students from all the fourth-grade classes entered. (3) The judges choices were announced on Thursday. (4) My friend Basil won first place for his poem about the sea. (5) “I can’t believe it! he shouted. (6) His parents were very proud and hopefull. (7) The winners poems will be printed in the school newspaper."],"intro":"Anas wrote about a contest. His draft has some mistakes. Read it and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which word correctly completes the sentence?\n“The poems will be printed in ___ newspaper next week.”","o":["our","hour","are","ower"],"k":"A","sk":"Spells grade-level words correctly","b":"161–170","g":"ME"},{"n":2,"t":"mc","s":"What is the correct way to write sentence 5?","o":["I can’t believe it! “he shouted.”","“I can’t believe it” he shouted!","“I can’t believe it!” he shouted.","“I can’t believe it! he shouted.”"],"k":"C","sk":"Punctuates dialogue and quotations","b":"171–180","g":"ME"},{"n":3,"t":"mc","s":"Which word in sentence 6 is spelled wrong?","o":["proud","very","parents","hopefull"],"k":"D","sk":"Spells words with prefixes and suffixes correctly","b":"171–180","g":"ME"},{"n":4,"t":"mc","s":"Which word correctly completes the sentence?\n“Basil read his poem ___ and clearly.”","o":["slowley","slowly","slowlly","slowely"],"k":"B","sk":"Spells words with prefixes and suffixes correctly","b":"171–180","g":"ME"},{"n":5,"t":"mc","s":"Which word in sentence 3 needs an apostrophe?","o":["were","judges","announced","choices"],"k":"B","sk":"Uses apostrophes in contractions and possessives","b":"181–190","g":"ME"},{"n":6,"t":"mc","s":"Which word correctly completes the sentence?\n“The judges were ___ about the poems.”","o":["seriuos","sereous","serius","serious"],"k":"D","sk":"Spells grade-level words correctly","b":"181–190","g":"ME"},{"n":7,"t":"mc","s":"What is the correct way to write sentence 7?","o":["The winners’ poems will be printed in the school newspaper.","The winners’s poems will be printed in the school newspaper.","The winner’s poem’s will be printed in the school newspaper.","The winners poem’s will be printed in the school newspaper."],"k":"A","sk":"Uses apostrophes in contractions and possessives","b":"191–200","g":"ME"}]}]}],"mocks":[{"id":"A","note":"Full practice test · 43 questions","sections":[{"passage":{"title":"The Water Cycle","genre":"draft","paras":["(1) Water moves around the Earth in a never-ending cycle. (2) First, the sun heats water in oceans, lakes and rivers. (3) The water turn into a gas called water vapor. (4) This process is called evaporation. (5) Next, the vapor rises and cools to form clouds. (6) My uncle is a pilot who flies above the clouds. (7) When the clouds get heavy water falls as rain or snow. (8) Finally, the water flows back into oceans and lakes, and the cycle starts again."],"intro":"Mazen is writing a report about the water cycle. Read his draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which sentence does NOT belong in the report?","o":["sentence 2","sentence 4","sentence 6","sentence 8"],"k":"C","sk":"Identifies a sentence that does not belong","b":"161–170","g":"WR"},{"n":2,"t":"mc","s":"Which sentence BEST states the main idea of the report?","o":["sentence 1","sentence 3","sentence 5","sentence 7"],"k":"A","sk":"Chooses a topic sentence that introduces the main idea","b":"161–170","g":"WR"},{"n":3,"t":"mc","s":"What is the correct way to write sentence 3?","o":["The water turning into a gas called water vapor.","The water turns into a gas called water vapor.","The water have turned into a gas called water vapor.","The water are turning into a gas called water vapor."],"k":"B","sk":"Makes subjects and verbs agree","b":"171–180","g":"GU"},{"n":4,"t":"mc","s":"Which source would BEST help Mazen check his facts?","o":["a song about rainy days and puddles","a novel about a boat lost at sea","an advertisement for new umbrellas","an encyclopedia article about weather"],"k":"D","sk":"Chooses a useful source or research question","b":"171–180","g":"WR"},{"n":5,"t":"mc","s":"Mazen wants to explain the word condensation. Which sentence would BEST fit after sentence 5?","o":["Clouds can be white, gray or even pink when the sun sets.","Condensation is a long word that has a lot of letters in it.","This cooling of vapor into tiny drops is called condensation.","Some people like to lie on the grass and watch the clouds."],"k":"C","sk":"Adds a detail that supports the main idea","b":"181–190","g":"WR"},{"n":6,"t":"mc","s":"What is the correct way to write sentence 7?","o":["When the clouds get heavy water, falls as rain or snow.","When the clouds get heavy, water falls as rain or snow.","When the clouds, get heavy water falls as rain or snow.","When, the clouds get heavy water falls as rain or snow."],"k":"B","sk":"Uses a comma after an introductory word, phrase or clause","b":"181–190","g":"ME"}]},{"passage":{"title":"Grandpa’s Old Radio","genre":"draft","paras":["(1) In Grandpas storeroom, I found an old wooden radio covered in dust. (2) “Does it still work?” I asked. (3) Grandpa laughed and said, “Let’s find out.” (4) He wiped the dust off with a cloth. (5) He turned the big knob slowly. (6) At first, we heard only crackling. (7) Then a man’s voice reading the news filled the room! (8) Grandpa told me he listened to that radio every night when he were a boy."],"intro":"Ammar wrote a story about his grandfather. Read his draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"Which word in sentence 7 shows the order of events?","o":["room","news","voice","Then"],"k":"D","sk":"Chooses a transition that connects ideas","b":"161–170","g":"WR"},{"n":8,"t":"mc","s":"Which word could replace “turned” in sentence 5 to show exactly how Grandpa moved the knob?","o":["twisted","made","did","had"],"k":"A","sk":"Chooses precise or vivid language","b":"161–170","g":"WR"},{"n":9,"t":"mc","s":"How should “Grandpas” in sentence 1 be written?","o":["Grandpa’s","Grandpas’s","Grandpa’es","Grandpas’"],"k":"A","sk":"Uses apostrophes in contractions and possessives","b":"171–180","g":"ME"},{"n":10,"t":"mc","s":"Which sentence could Ammar add after sentence 1 to describe the radio?","o":["Dust can make some people sneeze again and again.","Radios were invented more than a hundred years ago.","My grandfather’s house is close to the big mosque.","It had a cracked glass dial and two shiny brass knobs."],"k":"D","sk":"Uses narrative techniques: dialogue, description and pacing","b":"171–180","g":"WR"},{"n":11,"t":"mc","s":"What is the correct way to write the end of sentence 8?","o":["when he is a boy.","when he was a boy.","when he be a boy.","when he were boys."],"k":"B","sk":"Uses verb tenses correctly","b":"171–180","g":"GU"},{"n":12,"t":"mc","s":"Which sentence would be the BEST ending for the story?","o":["The storeroom was full of dusty boxes, old chairs and broken lamps.","Radios today are much smaller than the radios of long ago.","Now Grandpa and I listen to the old radio together every evening.","In Grandpa’s storeroom, I found an old radio full of dust."],"k":"C","sk":"Chooses an effective concluding sentence","b":"181–190","g":"WR"}]},{"passage":{"title":"Recess Should Be Longer","genre":"draft","paras":["(1) I believe our recess should be longer. (2) Right now we have only fifteen minutes. (3) That is not enough time to eat a snack and play a game. (4) Students who plays outside come back to class ready to learn. (5) Also, recess helps us make friends. (6) My favorite subject is math. (7) Some teachers say longer recess means less time for lessons. (8) However, students learn better when they have had a break."],"intro":"Abdullah wrote an opinion piece for the school newspaper. Read his draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"Which sentence does NOT belong in the opinion piece?","o":["sentence 3","sentence 5","sentence 6","sentence 7"],"k":"C","sk":"Identifies a sentence that does not belong","b":"161–170","g":"WR"},{"n":14,"t":"mc","s":"Which sentence states Abdullah’s opinion?","o":["sentence 1","sentence 2","sentence 3","sentence 5"],"k":"A","sk":"States a clear claim or thesis","b":"161–170","g":"WR"},{"n":15,"t":"mc","s":"What is the correct way to write sentence 2?","o":["Right now we, have only fifteen minutes.","Right now, we have only fifteen minutes.","Right now we have only, fifteen minutes.","Right, now we have only fifteen minutes."],"k":"B","sk":"Uses a comma after an introductory word, phrase or clause","b":"171–180","g":"ME"},{"n":16,"t":"mc","s":"What is the correct way to write sentence 4?","o":["Students who playing outside come back to class ready to learn.","Student who play outside come back to class ready to learn.","Students who plays outside comes back to class ready to learn.","Students who play outside come back to class ready to learn."],"k":"D","sk":"Makes subjects and verbs agree","b":"171–180","g":"GU"},{"n":17,"t":"mc","s":"In which sentence does Abdullah describe an opposing view?","o":["sentence 4","sentence 5","sentence 7","sentence 8"],"k":"C","sk":"Acknowledges and answers an opposing claim","b":"181–190","g":"WR"},{"n":18,"t":"mc","s":"Which sentence would BEST support sentence 4?","o":["Some students like to read quiet books during recess.","The bell rings at ten o’clock every school day.","Our playground has two swings and a long slide.","Studies show that short breaks help students focus."],"k":"D","sk":"Chooses relevant evidence to support a point","b":"181–190","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Which sentence would be the BEST topic sentence for a paragraph about the benefits of reading?","o":["Reading every day helps students in many ways.","The school library closes at three o’clock.","Some books have hard covers, and some do not.","My sister reads in her room before she sleeps."],"k":"A","sk":"Chooses a topic sentence that introduces the main idea","b":"171–180","g":"WR"},{"n":20,"t":"mc","s":"Which sentence uses the MOST precise language?","o":["The falcon moved in a quick kind of way.","The falcon dove at eighty kilometers an hour.","The bird went really fast in the sky that day.","The bird was fast and did a fast thing."],"k":"B","sk":"Chooses precise or vivid language","b":"171–180","g":"WR"},{"n":21,"t":"mc","s":"Which word BEST completes the sentence?\n“Many animals sleep at night. Owls, ___, hunt at night.”","o":["however","also","first","for example"],"k":"A","sk":"Chooses a transition that connects ideas","b":"181–190","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which words correctly complete the sentence?\n“Right now, the children ___ in the pool.”","o":["swimmed","is swimming","were swimming","are swimming"],"k":"D","sk":"Uses progressive verb tenses","b":"161–170","g":"GU"},{"n":23,"t":"mc","s":"Which word correctly completes the sentence?\n“The cat jumped ___ the fence.”","o":["since","over","of","at"],"k":"B","sk":"Uses prepositions and prepositional phrases","b":"161–170","g":"GU"},{"n":24,"t":"mc","s":"Which word correctly completes the sentence?\n“This is the book ___ I told you about.”","o":["whom","whose","that","who"],"k":"C","sk":"Uses relative pronouns and relative adverbs","b":"171–180","g":"GU"},{"n":25,"t":"mc","s":"Which word correctly completes the sentence?\n“___ I borrow your pencil, please?”","o":["May","Should","Must","Will"],"k":"A","sk":"Uses modal auxiliaries","b":"171–180","g":"GU"},{"n":26,"t":"mc","s":"Which word correctly completes the sentence?\n“___ going to the market after school.”","o":["There","Theyre","Their","They’re"],"k":"D","sk":"Chooses between frequently confused words","b":"171–180","g":"GU"},{"n":27,"t":"mc","s":"Which word correctly completes the sentence?\n“My sister and I cleaned ___ room.”","o":["us","ours","our","we"],"k":"C","sk":"Uses pronouns correctly","b":"171–180","g":"GU"},{"n":28,"t":"mc","s":"Which word correctly completes the sentence?\n“The leaves on the tree ___ turning yellow.”","o":["be","are","was","is"],"k":"B","sk":"Makes subjects and verbs agree","b":"181–190","g":"GU"},{"n":29,"t":"mc","s":"Which of these is a complete sentence?","o":["Although it was late, we kept reading.","Because we kept reading so late.","Kept reading although it was very late.","Although it was late at night."],"k":"A","sk":"Recognizes complete sentences, fragments and run-ons","b":"181–190","g":"GU"},{"n":30,"t":"mc","s":"Which is the BEST way to correct this run-on sentence?\n“The library was quiet I could hear the clock ticking.”","o":["The library, was quiet I could hear the clock ticking.","The library was quiet, so I could hear the clock ticking.","The library was quiet, I could hear the clock ticking.","The library was quiet so, I could hear the clock ticking."],"k":"B","sk":"Recognizes complete sentences, fragments and run-ons","b":"181–190","g":"GU"},{"n":31,"t":"mc","s":"Which sentence lists the adjectives in the correct order?","o":["We saw an old huge stone castle.","We saw a stone huge old castle.","We saw a huge old stone castle.","We saw a huge stone old castle."],"k":"C","sk":"Uses adjectives and adverbs correctly, including comparisons","b":"191–200","g":"GU"},{"n":32,"t":"mc","s":"Which word correctly completes the sentence?\n“By the time we arrived, the movie had already ___.”","o":["beginned","began","begin","begun"],"k":"D","sk":"Forms irregular past-tense and past-participle verbs","b":"201–210","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence is written correctly?","o":["We celebrated national day on September 23.","We Celebrated National day on September 23.","We celebrated National Day on september 23.","We celebrated National Day on September 23."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"161–170","g":"ME"},{"n":34,"t":"mc","s":"Which word correctly completes the sentence?\n“They ___ finished their work yet.”","o":["haven’t","havent","have’nt","havent’"],"k":"A","sk":"Uses apostrophes in contractions and possessives","b":"161–170","g":"ME"},{"n":35,"t":"mc","s":"Which sentence uses a comma correctly?","o":["I studied, for the test and I got a good grade.","I studied for the test, and I got a good grade.","I studied for the test and I got, a good grade.","I studied for the test and, I got a good grade."],"k":"B","sk":"Uses a comma before a conjunction in a compound sentence","b":"171–180","g":"ME"},{"n":36,"t":"mc","s":"Which sentence uses a comma correctly?","o":["No we, cannot go outside yet.","No we cannot go, outside yet.","No, we cannot go outside yet.","No we cannot go outside, yet."],"k":"C","sk":"Uses a comma after an introductory word, phrase or clause","b":"171–180","g":"ME"},{"n":37,"t":"mc","s":"Which word correctly completes the sentence?\n“Be ___ when you cross the street.”","o":["carful","careful","carefull","carefule"],"k":"B","sk":"Spells words with prefixes and suffixes correctly","b":"171–180","g":"ME"},{"n":38,"t":"mc","s":"Which word correctly completes the sentence?\n“The wind ___ the leaves off the trees.”","o":["blew","blue","bleu","blewe"],"k":"A","sk":"Spells grade-level words correctly","b":"171–180","g":"ME"},{"n":39,"t":"mc","s":"Which book title is written correctly?","o":["A Journey To The Center Of The Desert","a journey to the center of the desert","A Journey to the Center of the Desert","A journey to the Center of the desert"],"k":"C","sk":"Capitalizes and punctuates titles of works","b":"181–190","g":"ME"},{"n":40,"t":"mc","s":"Which sentence uses a comma correctly?","o":["Thank you for, the gift Aunt Nora.","Thank you for the gift Aunt, Nora.","Thank you, for the gift Aunt Nora.","Thank you for the gift, Aunt Nora."],"k":"D","sk":"Uses a comma after an introductory word, phrase or clause","b":"181–190","g":"ME"},{"n":41,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Have you finished your project? “asked Mr. Saad.”","“Have you finished your project?” Asked Mr. Saad.","“Have you finished your project,” asked Mr. Saad?","“Have you finished your project?” asked Mr. Saad."],"k":"D","sk":"Punctuates dialogue and quotations","b":"181–190","g":"ME"},{"n":42,"t":"mc","s":"Which word is spelled correctly?","o":["February","Febrary","Febuary","Februery"],"k":"A","sk":"Spells grade-level words correctly","b":"181–190","g":"ME"},{"n":43,"t":"mc","s":"The toys belong to my two sisters. Which sentence is written correctly?","o":["My sister’s toys are in the box.","My sisters’ toys are in the box.","My sisters’s toys are in the box.","My sisters toys are in the box."],"k":"B","sk":"Uses apostrophes in contractions and possessives","b":"191–200","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]},{"id":"B","note":"Full practice test · 43 questions","sections":[{"passage":{"title":"Volcanoes","genre":"draft","paras":["(1) A volcano is an opening in the Earth’s surface. (2) Deep underground, rock gets so hot that it melts. (3) This melted rock is called magma. (4) When pressure builds up, magma pushes up through the opening. (5) Once it reaches the surface, it is called lava. (6) Some volcanoes erupt often, but others has been quiet for thousands of years. (7) Mount fuji in Japan is a famous volcano. (8) Scientists who study volcanoes try to predict when they will erupt."],"intro":"Bader is writing a report about volcanoes. Read his draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which word in sentence 5 tells WHEN magma becomes lava?","o":["Once","reaches","surface","called"],"k":"A","sk":"Chooses a transition that connects ideas","b":"171–180","g":"WR"},{"n":2,"t":"mc","s":"Which word in sentence 7 should begin with a capital letter?","o":["famous","in","fuji","volcano"],"k":"C","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"171–180","g":"ME"},{"n":3,"t":"mc","s":"Which sentence would make a more interesting introduction than sentence 1?","o":["This is a report about volcanoes and also some other things too.","Imagine a mountain that can shoot fire and ash high into the sky!","Volcanoes are things that I am going to write about today.","A volcano is a mountain, and there are many volcanoes."],"k":"B","sk":"Chooses an effective introduction","b":"171–180","g":"WR"},{"n":4,"t":"mc","s":"Which word should replace “has” in sentence 6?","o":["having","was","is","have"],"k":"D","sk":"Makes subjects and verbs agree","b":"181–190","g":"GU"},{"n":5,"t":"mc","s":"Which sentence would BEST follow sentence 8 to support it?","o":["Some mountains are covered with snow all through the year.","Japan has many large, busy cities and some of the world’s fastest trains.","They measure small earthquakes and gases that come from the ground.","Lava is very hot, and it is also very bright and orange."],"k":"C","sk":"Adds a detail that supports the main idea","b":"181–190","g":"WR"},{"n":6,"t":"mc","s":"Which question would be BEST for Bader to research to add another paragraph?","o":["How do volcanoes change the land around them?","What is the name of my new science teacher?","Which volcano is the prettiest one to look at?","Do I like volcanoes more than earthquakes?"],"k":"A","sk":"Chooses a useful source or research question","b":"181–190","g":"WR"}]},{"passage":{"title":"How to Make a Bird Feeder","genre":"draft","paras":["(1) You can help birds in winter by making a simple bird feeder. (2) First, ask an adult to cut a hole in the side of a clean plastic bottle. (3) Next, push a wooden spoon through the bottle below the hole. (4) Birds can sit on the spoon. (5) Then, fill the bottle with birdseed. (6) Tie a string around the neck of the bottle and hang it from a tree. (7) Soon you will see birds visiting you’re feeder."],"intro":"Noor wrote directions for a class project. Read her draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"What is the main purpose of this draft?","o":["to tell a story about a winter trip","to persuade people to buy birdseed","to describe the birds in a garden","to explain how to make a bird feeder"],"k":"D","sk":"Chooses language that fits the purpose and audience","b":"161–170","g":"WR"},{"n":8,"t":"mc","s":"Which word BEST begins sentence 6?","o":["However,","Finally,","First,","For example,"],"k":"B","sk":"Chooses a transition that connects ideas","b":"161–170","g":"WR"},{"n":9,"t":"mc","s":"Which title BEST fits these directions?","o":["Make Your Own Bottle Bird Feeder","Birds of the World and Their Nests","My Winter Vacation in the Mountains","Why Plastic Bottles Are a Problem"],"k":"A","sk":"Chooses language that fits the purpose and audience","b":"171–180","g":"WR"},{"n":10,"t":"mc","s":"Which sentence would BEST fit after sentence 2 to make the step safer?","o":["Wooden spoons are very useful in the kitchen as well.","Some birds fly south when the weather gets very cold.","Never use scissors or a knife without an adult’s help.","Plastic bottles come in many sizes, shapes and colors."],"k":"C","sk":"Adds a detail that supports the main idea","b":"171–180","g":"WR"},{"n":11,"t":"mc","s":"Which word should replace “you’re” in sentence 7?","o":["you","youre","yours","your"],"k":"D","sk":"Spells grade-level words correctly","b":"171–180","g":"ME"},{"n":12,"t":"mc","s":"Which is the BEST way to combine sentences 3 and 4?","o":["Next, push a wooden spoon through the bottle below the hole birds can sit on it.","Next, push a wooden spoon through the bottle below the hole so birds can sit on it.","Next, push a wooden spoon, birds can sit, through the bottle below the hole.","Next, push a wooden spoon through the bottle below the hole, birds can sit on it."],"k":"B","sk":"Combines sentences correctly","b":"181–190","g":"GU"}]},{"passage":{"title":"A Letter to the Mayor","genre":"draft","paras":["Dear Mayor Al-Harbi,","(1) My name is Waleed, and I am a fourth-grade student at al-noor school. (2) I am writing to ask you to build a park in our neighborhood. (3) Right now, children play in the street, which is dangerous. (4) A park would gives us a safe place to play and exercise. (5) It could also be a place where families meet. (6) I know that parks cost a lot of money. (7) But many families would use it every day. (8) Thank you for reading my letter.","Sincerely,","Waleed"],"intro":"Waleed wrote a letter to the mayor of his city. Read his draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"Why does Waleed give his name and school in sentence 1?","o":["to explain how to build a park","to show that he is good at writing","to describe his favorite teacher","to introduce himself to the mayor"],"k":"D","sk":"Chooses language that fits the purpose and audience","b":"161–170","g":"WR"},{"n":14,"t":"mc","s":"What is the correct way to write the end of sentence 1?","o":["a fourth-grade student at al-Noor School.","a fourth-grade student at Al-noor school.","a fourth-grade student at Al-Noor School.","a Fourth-Grade Student at Al-Noor School."],"k":"C","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"171–180","g":"ME"},{"n":15,"t":"mc","s":"What is the correct way to write sentence 4?","o":["A park would gave us a safe place to play and exercise.","A park would give us a safe place to play and exercise.","A park would giving us a safe place to play and exercise.","A park would given us a safe place to play and exercise."],"k":"B","sk":"Uses modal auxiliaries","b":"171–180","g":"GU"},{"n":16,"t":"mc","s":"Which sentence shows that Waleed understands a problem the mayor may have?","o":["sentence 2","sentence 4","sentence 6","sentence 8"],"k":"C","sk":"Acknowledges and answers an opposing claim","b":"181–190","g":"WR"},{"n":17,"t":"mc","s":"Which sentence would BEST support sentence 3?","o":["Last month, a boy on our street was almost hit by a car.","Our street has twelve houses and one small grocery shop.","Cars come in many colors, such as red, white and gray.","Many children in my class like to play soccer at school."],"k":"A","sk":"Chooses relevant evidence to support a point","b":"181–190","g":"WR"},{"n":18,"t":"mc","s":"Which word could replace “But” in sentence 7 to sound more formal?","o":["So,","However,","Also,","Then,"],"k":"B","sk":"Chooses a transition that connects ideas","b":"181–190","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Read the sentences.\n1. Then she mixed in the flour.\n2. Finally, she baked the cookies for twelve minutes.\n3. First, Mona melted the butter.\nWhat is the BEST order for these sentences?","o":["3, 2, 1","1, 3, 2","2, 3, 1","3, 1, 2"],"k":"D","sk":"Puts sentences or events in a logical order","b":"171–180","g":"WR"},{"n":20,"t":"mc","s":"Which sentence would be BEST in a report for a teacher?","o":["The Arabian leopard is an endangered animal.","So yeah, leopards are, like, in danger.","Wow, leopards are the best animals ever!","Arabian leopards are super cool, you know?"],"k":"A","sk":"Keeps a consistent formal style and objective tone","b":"171–180","g":"WR"},{"n":21,"t":"mc","s":"Which sentence is the clearest and least wordy?","o":["At nine is when the library opens, at nine o’clock.","The library, it opens at nine o’clock in the morning time.","The library opens at nine.","The library is a place that opens at nine, which is when it opens."],"k":"C","sk":"Revises to remove wordy or repeated language","b":"181–190","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which prepositional phrase BEST completes the sentence?\n“The children waited ___ until the bell rang.”","o":["in the hallway","in hallway the","the hallway in","hallway in the"],"k":"A","sk":"Uses prepositions and prepositional phrases","b":"161–170","g":"GU"},{"n":23,"t":"mc","s":"Which word BEST completes the sentence?\n“The sky is dark. It ___ rain soon.”","o":["can’t","might","mustn’t","shouldn’t"],"k":"B","sk":"Uses modal auxiliaries","b":"171–180","g":"GU"},{"n":24,"t":"mc","s":"Which words correctly complete the sentence?\n“This is the ___ book in the whole library.”","o":["most interestinger","interestingest","more interesting","most interesting"],"k":"D","sk":"Uses adjectives and adverbs correctly, including comparisons","b":"171–180","g":"GU"},{"n":25,"t":"mc","s":"Which group of words is a fragment?","o":["The bus was late this morning.","I missed class because the bus was late.","The bus was late, so I walked.","Because the bus was late this morning."],"k":"D","sk":"Recognizes complete sentences, fragments and run-ons","b":"171–180","g":"GU"},{"n":26,"t":"mc","s":"Which word correctly completes the sentence?\n“Do you know the boy ___ bike is red?”","o":["whose","who’s","which","who"],"k":"A","sk":"Uses relative pronouns and relative adverbs","b":"181–190","g":"GU"},{"n":27,"t":"mc","s":"Which words correctly complete the sentence?\n“Tomorrow at noon, we ___ to Riyadh.”","o":["flying","will be flying","were flying","are flew"],"k":"B","sk":"Uses progressive verb tenses","b":"181–190","g":"GU"},{"n":28,"t":"mc","s":"Which words correctly complete the sentence?\n“Faris reads ___ than his brother.”","o":["most carefully","carefuller","more carefully","more careful"],"k":"C","sk":"Uses adjectives and adverbs correctly, including comparisons","b":"181–190","g":"GU"},{"n":29,"t":"mc","s":"Which word correctly completes the sentence?\n“The puppy wagged ___ tail.”","o":["its","it’s","its’","it"],"k":"A","sk":"Chooses between frequently confused words","b":"181–190","g":"GU"},{"n":30,"t":"mc","s":"Which is the BEST way to combine the sentences?\n“The museum was crowded. We still enjoyed the exhibits.”","o":["The museum was crowded so we still enjoyed the exhibits.","The museum was crowded, but we still enjoyed the exhibits.","The museum was crowded but, we still enjoyed the exhibits.","The museum was crowded, we still enjoyed the exhibits."],"k":"B","sk":"Combines sentences correctly","b":"181–190","g":"GU"},{"n":31,"t":"mc","s":"Which word correctly completes the sentence?\n“Have you ever ___ a camel?”","o":["rided","rode","ride","ridden"],"k":"D","sk":"Forms irregular past-tense and past-participle verbs","b":"191–200","g":"GU"},{"n":32,"t":"mc","s":"Which word correctly completes the sentence?\n“Everybody in my family ___ to wake up early.”","o":["have","were having","has","are having"],"k":"C","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence is written correctly?","o":["the Nile River flows through Egypt.","The Nile River flows through Egypt.","The nile river flows through Egypt.","The Nile river flows through egypt."],"k":"B","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"161–170","g":"ME"},{"n":34,"t":"mc","s":"Which sentence uses a comma correctly?","o":["Well I think, we should leave now.","Well I think we should, leave now.","Well, I think we should leave now.","Well I, think we should leave now."],"k":"C","sk":"Uses a comma after an introductory word, phrase or clause","b":"171–180","g":"ME"},{"n":35,"t":"mc","s":"Which sentence uses a comma correctly?","o":["Hamza did you, feed the cat?","Hamza did, you feed the cat?","Hamza did you feed, the cat?","Hamza, did you feed the cat?"],"k":"D","sk":"Uses a comma after an introductory word, phrase or clause","b":"171–180","g":"ME"},{"n":36,"t":"mc","s":"Which word is spelled correctly?","o":["believe","beleave","beleive","belive"],"k":"A","sk":"Spells grade-level words correctly","b":"171–180","g":"ME"},{"n":37,"t":"mc","s":"Which word correctly completes the sentence?\n“Please ___ the door when you leave.”","o":["clothes","closse","cloze","close"],"k":"D","sk":"Spells grade-level words correctly","b":"171–180","g":"ME"},{"n":38,"t":"mc","s":"Which sentence is written correctly?","o":["My Uncle is a doctor at King Faisal Hospital.","My uncle is a doctor at king faisal hospital.","My uncle is a doctor at King Faisal Hospital.","My uncle is a Doctor at King Faisal hospital."],"k":"C","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"181–190","g":"ME"},{"n":39,"t":"mc","s":"Which address is written correctly?","o":["12, Palm Street Taif Saudi Arabia","12 Palm Street, Taif, Saudi Arabia","12 palm Street, Taif Saudi, Arabia","12 Palm street Taif, Saudi Arabia"],"k":"B","sk":"Uses commas in dates, addresses and letters","b":"181–190","g":"ME"},{"n":40,"t":"mc","s":"Which sentence uses a comma correctly?","o":["We could watch a movie, or we could play outside.","We could watch a movie or we could, play outside.","We could watch, a movie or we could play outside.","We could watch a movie or, we could play outside."],"k":"A","sk":"Uses a comma before a conjunction in a compound sentence","b":"181–190","g":"ME"},{"n":41,"t":"mc","s":"Which word correctly completes the sentence?\n“The puppy was ___ when it saw its owner.”","o":["excitted","exited","excited","exsited"],"k":"C","sk":"Spells words with prefixes and suffixes correctly","b":"181–190","g":"ME"},{"n":42,"t":"mc","s":"Which sentence is written correctly?","o":["The children’s book’s are on the top shelf.","The children’s books are on the top shelf.","The childrens books are on the top shelf.","The childrens’ books are on the top shelf."],"k":"B","sk":"Uses apostrophes in contractions and possessives","b":"191–200","g":"ME"},{"n":43,"t":"mc","s":"Which sentence is punctuated correctly?","o":["“If you hurry,” said Mom, “we can catch the bus.”","“If you hurry,” said Mom “we can catch the bus.”","“If you hurry” said Mom, “we can catch the bus.”","“If you hurry, said Mom, we can catch the bus.”"],"k":"A","sk":"Punctuates dialogue and quotations","b":"201–210","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]},{"id":"C","note":"Full practice test · 43 questions · harder","sections":[{"passage":{"title":"The Arabian Oryx","genre":"draft","paras":["(1) The Arabian oryx is a white antelope with long, straight horns. (2) It lives in the deserts of the arabian peninsula. (3) The oryx can go for weeks without drinking water. (4) It gets water from the plants it eats. (5) By 1972, there were no wild oryx left because of hunting. (6) Zoos and wildlife parks has bred oryx and returned them to the wild. (7) Today, there are more than a thousand oryx living in the wild again."],"intro":"Hassan is writing a report about an endangered animal. Read his draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"What is the correct way to write the end of sentence 2?","o":["the deserts of the Arabian Peninsula.","the deserts of The Arabian peninsula.","the Deserts of the Arabian Peninsula.","the deserts of the Arabian peninsula."],"k":"A","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"171–180","g":"ME"},{"n":2,"t":"mc","s":"Which sentence would BEST follow sentence 1 to add description?","o":["Horns are made of a hard material like nails.","My cousin saw a giraffe at the zoo in Riyadh.","Many different kinds of antelope live in Africa and Asia.","Its white coat reflects the heat of the desert sun."],"k":"D","sk":"Adds a detail that supports the main idea","b":"171–180","g":"WR"},{"n":3,"t":"mc","s":"Which phrase could BEST begin sentence 6 to show a change?","o":["In the same way,","Fortunately,","For example,","First of all,"],"k":"B","sk":"Chooses a transition that connects ideas","b":"181–190","g":"WR"},{"n":4,"t":"mc","s":"Which word should replace “has” in sentence 6?","o":["was","is","have","having"],"k":"C","sk":"Makes subjects and verbs agree","b":"181–190","g":"GU"},{"n":5,"t":"mc","s":"Which sentence would be the BEST conclusion for the report?","o":["My favorite animal at the zoo is the elephant with its long trunk.","Some deserts get very little rain, and others get almost none.","The oryx’s return shows that people can help save endangered animals.","The oryx is white, and it has two long horns on top of its head."],"k":"C","sk":"Chooses an effective concluding sentence","b":"181–190","g":"WR"},{"n":6,"t":"mc","s":"Which source would be the MOST reliable for facts about the oryx today?","o":["a fairy tale about a magic white antelope","a comment posted online by an unknown user","an old calendar with pictures of animals","the website of a wildlife conservation group"],"k":"D","sk":"Chooses a useful source or research question","b":"191–200","g":"WR"}]},{"passage":{"title":"The Big Race","genre":"draft","paras":["(1) The whistle blew, and the race began. (2) Yaser ran as fast as he could, but two boys was ahead of him. (3) His legs felt heavy, and his breath came in short gasps. (4) Then he remembered his coach’s words: “Keep your eyes on the finish line.” (5) He pumped his arms harder. (6) One by one, he passed the other runners. (7) He crossed the finish line first."],"intro":"Raed wrote a story about a race. Read his draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"Which word should replace “was” in sentence 2?","o":["be","were","been","is"],"k":"B","sk":"Makes subjects and verbs agree","b":"171–180","g":"GU"},{"n":8,"t":"mc","s":"Why does “coach’s” in sentence 4 have an apostrophe?","o":["to show that the words belong to the coach","to show that a letter is missing from “coach”","to show that the coach is shouting loudly","to show that there is more than one coach"],"k":"A","sk":"Uses apostrophes in contractions and possessives","b":"171–180","g":"ME"},{"n":9,"t":"mc","s":"Which word could replace “ran” in sentence 2 to show more action?","o":["was","moved","sprinted","went"],"k":"C","sk":"Chooses precise or vivid language","b":"171–180","g":"WR"},{"n":10,"t":"mc","s":"Which phrase in sentence 6 shows how the action happened over time?","o":["One by one","the other","runners","he passed"],"k":"A","sk":"Chooses a transition that connects ideas","b":"181–190","g":"WR"},{"n":11,"t":"mc","s":"Which sentence could Raed add after sentence 7 to show how Yaser felt?","o":["The coach had a whistle and a white cap.","Some of the runners wore bright blue shoes.","The race was exactly four hundred meters long.","A huge smile spread across his tired face."],"k":"D","sk":"Uses narrative techniques: dialogue, description and pacing","b":"181–190","g":"WR"},{"n":12,"t":"mc","s":"Which sentence could Raed add before sentence 1 to build excitement?","o":["Races are held at the school every year in the month of May.","Yaser’s heart pounded as he waited at the starting line.","Yaser has two older sisters and one younger brother at home.","The track is behind the main school building near the gate."],"k":"B","sk":"Uses narrative techniques: dialogue, description and pacing","b":"191–200","g":"WR"}]},{"passage":{"title":"Why Students Should Learn to Cook","genre":"draft","paras":["(1) Every student should learn how to cook. (2) Cooking teaches us to measure and follow directions carefully. (3) It also helps us make healthy choices about food. (4) When we cook at home we can help our families. (5) Some people think cooking is only for adults. (6) But even young students can makes simple dishes, like salads or sandwiches. (7) Learning to cook is a skill we will use for the rest of our lives."],"intro":"Leen’s brother Adel wrote an opinion piece. Read his draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"Which sentence states the writer’s claim?","o":["sentence 1","sentence 2","sentence 3","sentence 6"],"k":"A","sk":"States a clear claim or thesis","b":"171–180","g":"WR"},{"n":14,"t":"mc","s":"What is the correct way to write sentence 6?","o":["But even young students can making simple dishes, like salads or sandwiches.","But even young students can make simple dishes, like salads or sandwiches.","But even young students can made simple dishes, like salads or sandwiches.","But even young students can makes simple dishes, like salads or sandwiches."],"k":"B","sk":"Uses modal auxiliaries","b":"171–180","g":"GU"},{"n":15,"t":"mc","s":"What is the correct way to write sentence 4?","o":["When we cook at home we can help, our families.","When we cook, at home we can help our families.","When we cook at home, we can help our families.","When, we cook at home we can help our families."],"k":"C","sk":"Uses a comma after an introductory word, phrase or clause","b":"181–190","g":"ME"},{"n":16,"t":"mc","s":"Which sentence would BEST support sentence 3?","o":["My grandmother’s favorite color has always been dark blue.","Restaurants are often very busy on Thursday and Friday nights.","Some kitchens are very big and bright, and some kitchens are quite small.","When we cook, we can choose fresh vegetables instead of fried snacks."],"k":"D","sk":"Chooses relevant evidence to support a point","b":"181–190","g":"WR"},{"n":17,"t":"mc","s":"In which sentence does Adel describe an opposing view?","o":["sentence 2","sentence 4","sentence 5","sentence 7"],"k":"C","sk":"Acknowledges and answers an opposing claim","b":"181–190","g":"WR"},{"n":18,"t":"mc","s":"Which sentence restates the writer’s opinion in the conclusion?","o":["sentence 2","sentence 3","sentence 6","sentence 7"],"k":"D","sk":"Chooses an effective concluding sentence","b":"181–190","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Read the topic sentence.\n“Camels are well suited to desert life.”\nWhich detail BEST supports it?","o":["Their humps store fat that gives them energy when food is scarce.","Some people think camels are funny-looking animals.","Camels are bought and sold in markets in many different countries.","My uncle took a picture of a camel near the highway."],"k":"A","sk":"Adds a detail that supports the main idea","b":"171–180","g":"WR"},{"n":20,"t":"mc","s":"Which phrase BEST completes the sentences?\n“Rami practiced every day. ___, he won the spelling bee.”","o":["In the beginning","As a result","On the other hand","For example"],"k":"B","sk":"Chooses a transition that connects ideas","b":"181–190","g":"WR"},{"n":21,"t":"mc","s":"Ali wrote this note:\nBurj Khalifa – Dubai – 828 m tall – opened 2010\nWhich sentence uses the note correctly?","o":["Dubai opened in 2010, and the city is 828 meters tall today.","The Burj Khalifa in Dubai is 828 meters tall and opened in 2010.","The Burj Khalifa in Dubai was 828 years old when it opened in 2010.","The Burj Khalifa opened in 828 and is 2010 meters tall in Dubai."],"k":"B","sk":"Uses notes and facts accurately in writing","b":"191–200","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which word BEST completes the sentence?\n“You ___ eat so many sweets. They are bad for your teeth.”","o":["can","must","shouldn’t","will"],"k":"C","sk":"Uses modal auxiliaries","b":"171–180","g":"GU"},{"n":23,"t":"mc","s":"Which word correctly completes the sentence?\n“Ahmed is taller ___ his brother.”","o":["thane","that","then","than"],"k":"D","sk":"Chooses between frequently confused words","b":"171–180","g":"GU"},{"n":24,"t":"mc","s":"Which words correctly complete the sentence?\n“When the phone rang, Mom ___ dinner.”","o":["was cooking","cooks","will be cooking","is cooking"],"k":"A","sk":"Uses progressive verb tenses","b":"181–190","g":"GU"},{"n":25,"t":"mc","s":"Which word correctly completes the sentence?\n“A basket of oranges ___ on the table.”","o":["were sitting","are sitting","sits","sit"],"k":"C","sk":"Makes subjects and verbs agree","b":"181–190","g":"GU"},{"n":26,"t":"mc","s":"Which sentence is written correctly?","o":["My sister likes to paint and, she wants to be an artist.","My sister likes to paint she wants to be an artist.","My sister likes to paint, she wants to be an artist.","My sister likes to paint, and she wants to be an artist."],"k":"D","sk":"Recognizes complete sentences, fragments and run-ons","b":"181–190","g":"GU"},{"n":27,"t":"mc","s":"Which is the BEST way to combine the sentences?\n“The storm was strong. The trees did not fall.”","o":["The storm was strong and, the trees did not fall.","The storm was strong, but the trees did not fall.","The storm was strong, the trees did not fall.","The storm was strong, so the trees did not fall."],"k":"B","sk":"Combines sentences correctly","b":"181–190","g":"GU"},{"n":28,"t":"mc","s":"Which sentence lists the adjectives in the correct order?","o":["My uncle bought a beautiful new red car.","My uncle bought a beautiful red new car.","My uncle bought a red new beautiful car.","My uncle bought a new beautiful red car."],"k":"A","sk":"Uses adjectives and adverbs correctly, including comparisons","b":"191–200","g":"GU"},{"n":29,"t":"mc","s":"Which word correctly completes the sentence?\n“We have lived in Taif ___ 2020.”","o":["since","during","from","for"],"k":"A","sk":"Uses prepositions and prepositional phrases","b":"191–200","g":"GU"},{"n":30,"t":"mc","s":"Which word correctly completes the sentence?\n“The children made the cards ___.”","o":["himself","themselves","theirselves","themself"],"k":"B","sk":"Uses reflexive and intensive pronouns","b":"191–200","g":"GU"},{"n":31,"t":"mc","s":"Which word correctly completes the sentence?\n“The man ___ we met at the market was very kind.”","o":["what","which","whose","whom"],"k":"D","sk":"Uses relative pronouns and relative adverbs","b":"201–210","g":"GU"},{"n":32,"t":"mc","s":"Which word correctly completes the sentence?\n“The pond has ___ because of the cold.”","o":["froze","frozed","frozen","freezed"],"k":"C","sk":"Forms irregular past-tense and past-participle verbs","b":"201–210","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence is written correctly?","o":["The United nations was Founded in 1945.","The united nations was founded in 1945.","The United Nations was founded in 1945.","the United Nations was founded in 1945."],"k":"C","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"171–180","g":"ME"},{"n":34,"t":"mc","s":"Which sentence uses a comma correctly?","o":["The bus was full so, we waited for the next one.","The bus was full so we waited, for the next one.","The bus, was full so we waited for the next one.","The bus was full, so we waited for the next one."],"k":"D","sk":"Uses a comma before a conjunction in a compound sentence","b":"171–180","g":"ME"},{"n":35,"t":"mc","s":"Which sentence uses a comma correctly?","o":["Can you help me, Dad?","Can you help, me Dad?","Can, you help me Dad?","Can you, help me Dad?"],"k":"A","sk":"Uses a comma after an introductory word, phrase or clause","b":"171–180","g":"ME"},{"n":36,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Fahad, said “The test is tomorrow.”","Fahad said, “The test is tomorrow.”","Fahad said “The test is tomorrow”.","Fahad said, The test is “tomorrow.”"],"k":"B","sk":"Punctuates dialogue and quotations","b":"171–180","g":"ME"},{"n":37,"t":"mc","s":"Which word is spelled correctly?","o":["faverite","favorit","favrite","favorite"],"k":"D","sk":"Spells grade-level words correctly","b":"171–180","g":"ME"},{"n":38,"t":"mc","s":"Which sentence is written correctly?","o":["we drove across the Arabian Desert last spring.","We drove across the Arabian Desert last spring.","We drove across the Arabian desert last Spring.","We drove across the arabian desert last spring."],"k":"B","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"181–190","g":"ME"},{"n":39,"t":"mc","s":"Which sentence uses a comma correctly?","o":["After the game, we went out for dinner.","After the game we went, out for dinner.","After, the game we went out for dinner.","After the game we went out, for dinner."],"k":"A","sk":"Uses a comma after an introductory word, phrase or clause","b":"181–190","g":"ME"},{"n":40,"t":"mc","s":"Which word correctly completes the sentence?\n“The road was ___ after the storm.”","o":["muddie","mudddy","muddy","mudy"],"k":"C","sk":"Spells words with prefixes and suffixes correctly","b":"181–190","g":"ME"},{"n":41,"t":"mc","s":"Which word correctly completes the sentence?\n“I ___ the answer to the question.”","o":["gnew","new","knew","knue"],"k":"C","sk":"Spells grade-level words correctly","b":"181–190","g":"ME"},{"n":42,"t":"mc","s":"Which sentence shows the title of a story written correctly?","o":["We read the story “the clever fox.”","We read the story “The Clever Fox.”","We read the story “The clever Fox”.","We read the story The Clever “Fox.”"],"k":"B","sk":"Capitalizes and punctuates titles of works","b":"201–210","g":"ME"},{"n":43,"t":"mc","s":"Which sentence is written correctly?","o":["The womens’ team won the match.","The womens team won the match.","The women’s’ team won the match.","The women’s team won the match."],"k":"D","sk":"Uses apostrophes in contractions and possessives","b":"201–210","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]},{"id":"D","note":"Full practice test · 43 questions · harder","sections":[{"passage":{"title":"The First Airplane","genre":"draft","paras":["(1) For thousands of years, people dreamed of flying like birds. (2) In 1903, two brothers named Orville and Wilbur Wright made that dream come true. (3) They built an airplane with a small engine and wooden wings. (4) On December 17, 1903, Orville flew the plane for twelve seconds. (5) That may not sound long but it was the first powered flight in history. (6) The brothers flew three more times. (7) Today, airplanes carries millions of people around the world every day."],"intro":"Majid is writing a report about the history of flight. Read his draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which sentence BEST states the main idea of the report?","o":["sentence 2","sentence 3","sentence 6","sentence 7"],"k":"A","sk":"Chooses a topic sentence that introduces the main idea","b":"181–190","g":"WR"},{"n":2,"t":"mc","s":"Where should a comma be added in sentence 5?","o":["after “That”","after “flight”","after “sound”","after “long”"],"k":"D","sk":"Uses a comma before a conjunction in a compound sentence","b":"181–190","g":"ME"},{"n":3,"t":"mc","s":"Which phrase could BEST begin sentence 6?","o":["Long before,","Later that day,","For example,","In contrast,"],"k":"B","sk":"Chooses a transition that connects ideas","b":"181–190","g":"WR"},{"n":4,"t":"mc","s":"Which detail would BEST follow sentence 4?","o":["Some birds can fly for thousands of kilometers without stopping.","Many people today feel nervous when they ride in airplanes.","The plane traveled about 37 meters during that first flight.","Winter days can be very windy near the ocean in many places."],"k":"C","sk":"Adds a detail that supports the main idea","b":"181–190","g":"WR"},{"n":5,"t":"mc","s":"Which word should replace “carries” in sentence 7?","o":["has carried","carrying","is carrying","carry"],"k":"D","sk":"Makes subjects and verbs agree","b":"181–190","g":"GU"},{"n":6,"t":"mc","s":"Which sentence would be the BEST conclusion for the report?","o":["Birds were flying through the sky long before airplanes were built.","Orville flew the plane on a cold, windy morning in the middle of December.","The Wright brothers’ twelve-second flight changed the way the world travels.","Airplanes have wings, engines, wheels and seats for many people."],"k":"C","sk":"Chooses an effective concluding sentence","b":"191–200","g":"WR"}]},{"passage":{"title":"Lost in the Market","genre":"draft","paras":["(1) The old souq was crowded with shoppers. (2) I stopped to look at a shop full of shiny lamps. (3) When I turned around, my father was gone! (4) My heart beat fast. (5) I remembered what my mother always say: “If you get lost, stay where you are.” (6) So I stood next to the lamp shop and waited. (7) A few minutes later, I heard a familiar voice calling my name. (8) “There you are” my father said, hugging me tightly."],"intro":"Saud wrote a story about a day at the old market. Read his draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"Which phrase in sentence 7 shows that time has passed?","o":["A few minutes later","a familiar voice","I heard","my name"],"k":"A","sk":"Chooses a transition that connects ideas","b":"171–180","g":"WR"},{"n":8,"t":"mc","s":"Which word should replace “say” in sentence 5?","o":["sayes","says","saying","sayed"],"k":"B","sk":"Makes subjects and verbs agree","b":"181–190","g":"GU"},{"n":9,"t":"mc","s":"Which sentence could Saud add after sentence 4 to show how he felt?","o":["My hands felt cold, and I wanted to cry.","The souq has been there for many years.","My father teaches at a large high school.","Lamps are made of metal, wire and glass."],"k":"A","sk":"Uses narrative techniques: dialogue, description and pacing","b":"181–190","g":"WR"},{"n":10,"t":"mc","s":"Which revision of sentence 1 gives the reader the clearest picture?","o":["There were people at the souq, and it was a place where people were.","The souq was busy, and it was busy because of all the shoppers there.","The narrow lanes of the old souq were packed with shoppers and noisy sellers.","The souq was a place with lots of things and lots of people in it that day."],"k":"C","sk":"Chooses precise or vivid language","b":"191–200","g":"WR"},{"n":11,"t":"mc","s":"What is the correct way to write sentence 8?","o":["“There you are!” My father said, hugging me tightly.","There you are! “my father said, hugging me tightly.”","“There you are” my father said! hugging me tightly.","“There you are!” my father said, hugging me tightly."],"k":"D","sk":"Punctuates dialogue and quotations","b":"191–200","g":"ME"},{"n":12,"t":"mc","s":"Which sentence would be the BEST ending for the story?","o":["The old souq was crowded with many shoppers that morning.","From that day on, I always stayed close to my father in the souq.","The lamp shop sold more than a hundred lamps of every size and color.","My mother cooks rice and chicken for our family on Fridays."],"k":"B","sk":"Chooses an effective concluding sentence","b":"191–200","g":"WR"}]},{"passage":{"title":"Field Trip Report: The Aquarium","genre":"draft","paras":["(1) On Monday, Ms. Huda’s class visited the city aquarium. (2) The first tank holded hundreds of colorful fish from the Red Sea. (3) Next, we saw a giant octopus that changed colors. (4) Our guide explained that octopuses have three hearts. (5) The aquarium cafe sold delicious pizza. (6) The best part was the tunnel, where sharks swam over our heads! (7) we learned that many sea animals are in danger because of pollution."],"intro":"Khalid wrote a report for the school newsletter. Read his draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"Which sentence does NOT belong in the report?","o":["sentence 3","sentence 4","sentence 5","sentence 6"],"k":"C","sk":"Identifies a sentence that does not belong","b":"181–190","g":"WR"},{"n":14,"t":"mc","s":"Which word should replace “holded” in sentence 2?","o":["held","holding","holds","helded"],"k":"A","sk":"Forms irregular past-tense and past-participle verbs","b":"181–190","g":"GU"},{"n":15,"t":"mc","s":"What is the correct way to write sentence 7?","o":["we Learned that many sea animals are in danger because of pollution.","we learned that many Sea Animals are in danger because of pollution.","We learned that many sea animals are in Danger because of Pollution.","We learned that many sea animals are in danger because of pollution."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"181–190","g":"ME"},{"n":16,"t":"mc","s":"Who is the MOST LIKELY audience for this report?","o":["pilots who fly airplanes over the Red Sea","students and parents who read the school newsletter","scientists who study octopuses for a living","people who build glass fish tanks in large factories"],"k":"B","sk":"Chooses language that fits the purpose and audience","b":"181–190","g":"WR"},{"n":17,"t":"mc","s":"Which sentence would BEST follow sentence 7 to explain it?","o":["Our bus left the school at eight o’clock that morning.","Octopuses can be red, brown or nearly white in color.","Pizza is one of the most popular foods in the world.","Plastic bags in the ocean can harm turtles and fish."],"k":"D","sk":"Adds a detail that supports the main idea","b":"191–200","g":"WR"},{"n":18,"t":"mc","s":"Which sentence would make the BEST conclusion?","o":["Sharks are fish, and they live in oceans all around the world.","The trip taught us to care more about the ocean and the animals in it.","We will go to the aquarium again next year, or maybe we will not.","The aquarium has a cafe, a small gift shop and a very large parking lot."],"k":"B","sk":"Chooses an effective concluding sentence","b":"191–200","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Which sentence would be BEST to begin a formal letter to a museum director?","o":["Hey, can my whole class come to your awesome museum sometime?","Yo, my class really wants to see all your cool stuff!","I am writing to ask whether our class may visit your museum.","What’s up? We want to visit your museum soon, okay?"],"k":"C","sk":"Keeps a consistent formal style and objective tone","b":"181–190","g":"WR"},{"n":20,"t":"mc","s":"A paragraph about saving water includes these sentences. Which one does NOT belong?","o":["My favorite drink is cold orange juice.","Fix leaking pipes as soon as possible.","Turn off the tap while you brush your teeth.","Water garden plants early in the morning."],"k":"A","sk":"Identifies a sentence that does not belong","b":"181–190","g":"WR"},{"n":21,"t":"mc","s":"Which sentence BEST supports the claim “Exercise is good for the brain”?","o":["The brain is located inside the skull, which protects it from harm.","Many people go to the gym after work to exercise with their friends.","Good running shoes can be very expensive in most sports shops.","Research shows that exercise helps people remember information better."],"k":"D","sk":"Chooses relevant evidence to support a point","b":"201–210","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which words correctly complete the sentence?\n“Listen! The birds ___.”","o":["will sing","sang","are singing","were singing"],"k":"C","sk":"Uses progressive verb tenses","b":"171–180","g":"GU"},{"n":23,"t":"mc","s":"Which word correctly completes the sentence?\n“I would like ___ pieces of cake.”","o":["to","two","too","tow"],"k":"B","sk":"Chooses between frequently confused words","b":"171–180","g":"GU"},{"n":24,"t":"mc","s":"Which word correctly completes the sentence?\n“When I was five, I ___ swim.”","o":["could","must","will","can"],"k":"A","sk":"Uses modal auxiliaries","b":"181–190","g":"GU"},{"n":25,"t":"mc","s":"Which word correctly completes the sentence?\n“My cold is ___ today than it was yesterday.”","o":["badder","more bad","worst","worse"],"k":"D","sk":"Uses adjectives and adverbs correctly, including comparisons","b":"181–190","g":"GU"},{"n":26,"t":"mc","s":"Which word correctly completes the sentence?\n“The team played ___ in the second half.”","o":["baddest","badly","worstly","bad"],"k":"B","sk":"Uses adjectives and adverbs correctly, including comparisons","b":"191–200","g":"GU"},{"n":27,"t":"mc","s":"Which word correctly completes the sentence?\n“The cat hid ___ the sofa and the wall.”","o":["among","through","between","across"],"k":"C","sk":"Uses prepositions and prepositional phrases","b":"191–200","g":"GU"},{"n":28,"t":"mc","s":"Which is the BEST way to combine the sentences?\n“My aunt is a pilot. She flies to London every week.”","o":["My aunt, who is a pilot, flies to London every week.","My aunt who is a pilot flies, to London every week.","My aunt is a pilot, she flies to London every week.","My aunt, which is a pilot, flies to London every week."],"k":"A","sk":"Combines sentences correctly","b":"191–200","g":"GU"},{"n":29,"t":"mc","s":"Which word correctly completes the sentence?\n“Mathematics ___ my favorite subject.”","o":["be","are","is","were"],"k":"C","sk":"Makes subjects and verbs agree","b":"201–210","g":"GU"},{"n":30,"t":"mc","s":"Which word correctly completes the sentence?\n“The city ___ my father was born is near the sea.”","o":["who","whose","when","where"],"k":"D","sk":"Uses relative pronouns and relative adverbs","b":"201–210","g":"GU"},{"n":31,"t":"mc","s":"Which of these is a complete sentence?","o":["Because Leen practiced all week to win the prize.","Hoping to win the prize, Leen practiced all week.","Leen, who practiced all week to win.","Hoping to win the prize all week long."],"k":"B","sk":"Recognizes complete sentences, fragments and run-ons","b":"201–210","g":"GU"},{"n":32,"t":"mc","s":"Which word correctly completes the sentence?\n“The bell had already ___ when we got to class.”","o":["rung","ring","rang","ringed"],"k":"A","sk":"Forms irregular past-tense and past-participle verbs","b":"211–220","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence is written correctly?","o":["My grandmother speaks Arabic and english.","My Grandmother speaks arabic and English.","My grandmother speaks arabic and english.","My grandmother speaks Arabic and English."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"171–180","g":"ME"},{"n":34,"t":"mc","s":"Which sentence uses a comma correctly?","o":["Yes you may go to, the library.","Yes, you may go to the library.","Yes you, may go to the library.","Yes you may, go to the library."],"k":"B","sk":"Uses a comma after an introductory word, phrase or clause","b":"171–180","g":"ME"},{"n":35,"t":"mc","s":"Which word correctly completes the sentence?\n“Did you ___ the noise last night?”","o":["hear","here","heer","hare"],"k":"A","sk":"Spells grade-level words correctly","b":"171–180","g":"ME"},{"n":36,"t":"mc","s":"Which sentence uses a comma correctly?","o":["Leen likes to read but her brother, likes to draw.","Leen likes, to read but her brother likes to draw.","Leen likes to read, but her brother likes to draw.","Leen likes to read but, her brother likes to draw."],"k":"C","sk":"Uses a comma before a conjunction in a compound sentence","b":"181–190","g":"ME"},{"n":37,"t":"mc","s":"Which sentence uses commas correctly?","o":["We packed lunch filled, our bottles and drove to the beach.","We packed lunch filled our bottles, and, drove to the beach.","We packed lunch, filled our bottles and drove to the beach.","We packed, lunch filled our bottles and drove to the beach."],"k":"C","sk":"Uses commas in a series","b":"181–190","g":"ME"},{"n":38,"t":"mc","s":"Which sentence is punctuated correctly?","o":["“Watch out!” shouted the guard.","“Watch out,” shouted the guard!","“Watch out” shouted the guard!","Watch out! “shouted the guard.”"],"k":"A","sk":"Punctuates dialogue and quotations","b":"181–190","g":"ME"},{"n":39,"t":"mc","s":"Which word correctly completes the sentence?\n“Faris is the ___ boy in our class.”","o":["funiest","funnest","funnyest","funniest"],"k":"D","sk":"Spells words with prefixes and suffixes correctly","b":"181–190","g":"ME"},{"n":40,"t":"mc","s":"Which sentence is written correctly?","o":["Our class studied the Battle Of Badr in History.","Our class studied the Battle of Badr in history.","Our class studied the battle of badr in history.","Our class studied the battle of Badr in History."],"k":"B","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"191–200","g":"ME"},{"n":41,"t":"mc","s":"The meeting is for all of the teachers. Which sentence is written correctly?","o":["The teachers’ meeting starts at noon.","The teacher’s meeting starts at noon.","The teachers’s meeting starts at noon.","The teachers meeting’s starts at noon."],"k":"A","sk":"Uses apostrophes in contractions and possessives","b":"191–200","g":"ME"},{"n":42,"t":"mc","s":"Which sentence uses commas correctly?","o":["The meeting is on, Sunday March 8, 2026 at noon.","The meeting is on Sunday, March, 8 2026 at noon.","The meeting is on Sunday March 8 2026 at noon.","The meeting is on Sunday, March 8, 2026, at noon."],"k":"D","sk":"Uses commas in dates, addresses and letters","b":"201–210","g":"ME"},{"n":43,"t":"mc","s":"Which word is spelled correctly?","o":["separete","saparate","separate","seperate"],"k":"C","sk":"Spells grade-level words correctly","b":"201–210","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]},{"id":"E","note":"Final full practice test · 43 questions · hardest","sections":[{"passage":{"title":"Solar Energy","genre":"draft","paras":["(1) Solar energy is power that comes from the sun. (2) Solar panels collect sunlight and change it into electricity. (3) Many homes and schools now use solar panels on there roofs. (4) Solar energy is clean because it does not pollute the air. (5) It is also renewable, which means it will not run out. (6) However, solar panels do not make electricity at night. (7) Some homes stores extra energy in batteries for later use. (8) Saudi Arabia is building large solar farms in the desert."],"intro":"Ziad is writing a report about energy. Read his draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which word should replace “there” in sentence 3?","o":["thier","theirs","they’re","their"],"k":"D","sk":"Spells grade-level words correctly","b":"191–200","g":"ME"},{"n":2,"t":"mc","s":"Which phrase in sentence 5 explains the meaning of “renewable”?","o":["renewable","not run","which means it will not run out","It is also renewable"],"k":"C","sk":"Adds a detail that supports the main idea","b":"191–200","g":"WR"},{"n":3,"t":"mc","s":"Why does Ziad begin sentence 6 with “However”?","o":["to show the order of the steps","to introduce a problem with solar energy","to give one more example of clean energy","to repeat the main idea again"],"k":"B","sk":"Chooses a transition that connects ideas","b":"191–200","g":"WR"},{"n":4,"t":"mc","s":"Which word should replace “stores” in sentence 7?","o":["store","has stored","is storing","storing"],"k":"A","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"},{"n":5,"t":"mc","s":"Where would this sentence BEST fit?\n“This helps fight air pollution and keeps people healthy.”","o":["after sentence 1","after sentence 4","after sentence 6","after sentence 8"],"k":"B","sk":"Puts sentences or events in a logical order","b":"201–210","g":"WR"},{"n":6,"t":"mc","s":"Which sentence would be the BEST conclusion for the report?","o":["The sun rises in the east every morning and sets in the west.","Solar energy is power that comes to us from the sun every day.","Batteries come in many sizes, from tiny ones to very large ones for cars.","As technology improves, solar energy will power more and more of our world."],"k":"D","sk":"Chooses an effective concluding sentence","b":"201–210","g":"WR"}]},{"passage":{"title":"The Surprise Party","genre":"draft","paras":["(1) Mariam had been planning her mothers surprise party for weeks. (2) She invited aunts, cousins and neighbors. (3) On the big day, everyone hid in the dark living room. (4) “Shh! She’s coming!” whispered Mariam. (5) The door opened, and the lights flicked on. (6) “Surprise!” everyone shouted. (7) Mariam’s mother gasped and cover her mouth with both hands. (8) It was a wonderful night."],"intro":"Mariam wrote a story about a family celebration. Read her draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"How should “mothers” in sentence 1 be written?","o":["mothers’s","mothers’","mother’s","mother’es"],"k":"C","sk":"Uses apostrophes in contractions and possessives","b":"191–200","g":"ME"},{"n":8,"t":"mc","s":"Which phrase BEST begins sentence 5 to show that the moment came suddenly?","o":["All at once,","In the past,","For example,","In general,"],"k":"A","sk":"Chooses a transition that connects ideas","b":"191–200","g":"WR"},{"n":9,"t":"mc","s":"Why does the writer include dialogue in sentences 4 and 6?","o":["to make the scene feel lively and real","to give facts about birthdays in history","to list the guests in the order they came","to explain the steps for planning a party"],"k":"A","sk":"Uses narrative techniques: dialogue, description and pacing","b":"191–200","g":"WR"},{"n":10,"t":"mc","s":"What is the correct way to write sentence 7?","o":["Mariam’s mother gasps and covered her mouth with both hands.","Mariam’s mother gasped and covered her mouth with both hands.","Mariam’s mother gasping and cover her mouth with both hands.","Mariam’s mother gasped and covers her mouth with both hands."],"k":"B","sk":"Avoids inappropriate shifts in verb tense","b":"201–210","g":"GU"},{"n":11,"t":"mc","s":"Which sentence could be added after sentence 3 to build suspense?","o":["The living room has two large sofas and a soft red rug on the floor.","Parties can be fun for children and for adults of every age.","For several minutes, the only sound was the ticking of the clock.","Mariam’s favorite aunt lives far away in the city of Abha."],"k":"C","sk":"Uses narrative techniques: dialogue, description and pacing","b":"201–210","g":"WR"},{"n":12,"t":"mc","s":"Which sentence would be a stronger ending than sentence 8?","o":["Everyone ate some cake, and then they all drank some cold juice.","The party finally ended at ten o’clock, and all of the guests went home.","Mariam’s mother turned forty years old this year, in the spring.","With tears of joy, her mother hugged Mariam and whispered, “Thank you.”"],"k":"D","sk":"Chooses an effective concluding sentence","b":"201–210","g":"WR"}]},{"passage":{"title":"Should Schools Have Uniforms?","genre":"draft","paras":["(1) I think all schools should require uniforms. (2) First uniforms save families money because they don’t need to buy many different outfits. (3) Second, uniforms help students focus on learning instead of fashion. (4) Uniforms make everyone feel equal. (5) Some students says that uniforms stop them from showing their personalities. (6) However, they can still show who they are through their ideas, hobbies and talents. (7) For these reasons, uniforms are a smart choice for schools."],"intro":"Basem wrote an opinion essay. Read his draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"What is the correct way to begin sentence 2?","o":["First, uniforms save families money","First uniforms save, families money","First, uniforms, save families money","First uniforms, save families money"],"k":"A","sk":"Uses a comma after an introductory word, phrase or clause","b":"191–200","g":"ME"},{"n":14,"t":"mc","s":"Which word BEST begins sentence 4 to continue the list of reasons?","o":["For example,","Finally,","However,","Instead,"],"k":"B","sk":"Chooses a transition that connects ideas","b":"191–200","g":"WR"},{"n":15,"t":"mc","s":"Which word should replace “says” in sentence 5?","o":["has said","saying","say","is saying"],"k":"C","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"},{"n":16,"t":"mc","s":"Which sentence restates Basem’s claim at the end?","o":["sentence 2","sentence 4","sentence 5","sentence 7"],"k":"D","sk":"States a clear claim or thesis","b":"191–200","g":"WR"},{"n":17,"t":"mc","s":"Which sentence answers the opposing view in sentence 5?","o":["sentence 3","sentence 4","sentence 6","sentence 7"],"k":"C","sk":"Acknowledges and answers an opposing claim","b":"201–210","g":"WR"},{"n":18,"t":"mc","s":"Which sentence would BEST support sentence 3?","o":["Uniforms are often blue, gray or dark green, and they come with a white shirt.","When everyone dresses the same, students spend less time comparing clothes.","Fashion magazines show many new styles every single month.","Some schools in other countries are hundreds of years old."],"k":"B","sk":"Chooses relevant evidence to support a point","b":"201–210","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Which source would give the MOST trustworthy information about healthy eating?","o":["a website run by a children’s hospital","an advertisement for a new candy bar","a cartoon about talking vegetables","a post written by an unknown user"],"k":"A","sk":"Chooses a useful source or research question","b":"191–200","g":"WR"},{"n":20,"t":"mc","s":"A report about honey will have three paragraphs:\nA. How bees make honey\nB. Ways people use honey\nC. What honey is\nWhat is the MOST logical order?","o":["B, C, A","A, B, C","B, A, C","C, A, B"],"k":"D","sk":"Puts sentences or events in a logical order","b":"201–210","g":"WR"},{"n":21,"t":"mc","s":"Which revision of this sentence is the most concise?\n“In my opinion, I think that the park should be cleaned up because it is dirty and not clean.”","o":["The park, which is dirty and not clean, should be cleaned, I think.","In my opinion, I think the park should be cleaned because it is not clean.","The park should be cleaned because it is dirty.","I think, in my opinion, that the dirty park should be cleaned up and made clean."],"k":"C","sk":"Revises to remove wordy or repeated language","b":"211–220","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which words correctly complete the sentence?\n“While we ___ dinner, the lights went out.”","o":["were eating","eat","will be eating","are eating"],"k":"A","sk":"Uses progressive verb tenses","b":"191–200","g":"GU"},{"n":23,"t":"mc","s":"Which word BEST completes the sentence?\n“If you finish early, you ___ read a book.”","o":["won’t","may","must not","couldn’t"],"k":"B","sk":"Uses modal auxiliaries","b":"191–200","g":"GU"},{"n":24,"t":"mc","s":"Which word correctly completes the sentence?\n“I am interested ___ learning about space.”","o":["on","at","for","in"],"k":"D","sk":"Uses prepositions and prepositional phrases","b":"191–200","g":"GU"},{"n":25,"t":"mc","s":"Which sentence is a run-on?","o":["We arrived early the doors were still locked.","We arrived early, but the doors were locked.","When we arrived, the doors were still locked.","The doors were locked because we were early."],"k":"A","sk":"Recognizes complete sentences, fragments and run-ons","b":"191–200","g":"GU"},{"n":26,"t":"mc","s":"Which sentence lists the adjectives in the correct order?","o":["She wore a long pretty silk dress.","She wore a pretty silk long dress.","She wore a silk long pretty dress.","She wore a pretty long silk dress."],"k":"D","sk":"Uses adjectives and adverbs correctly, including comparisons","b":"201–210","g":"GU"},{"n":27,"t":"mc","s":"Which sentence is complete and correct?","o":["The students who had studied very hard for the exam.","Who had studied hard and passed the exam.","The students, who had studied hard, passed the exam.","Studied hard, the students who passed."],"k":"C","sk":"Recognizes complete sentences, fragments and run-ons","b":"201–210","g":"GU"},{"n":28,"t":"mc","s":"Which word correctly completes the sentence?\n“The coach gave the trophy to Sami and ___.”","o":["I","me","myself","mine"],"k":"B","sk":"Uses the correct pronoun case","b":"201–210","g":"GU"},{"n":29,"t":"mc","s":"Which word correctly completes the sentence?\n“The year ___ my brother was born, we moved to Jeddah.”","o":["which","when","who","where"],"k":"B","sk":"Uses relative pronouns and relative adverbs","b":"211–220","g":"GU"},{"n":30,"t":"mc","s":"Which word correctly completes the sentence?\n“Either my mother or my aunts ___ coming to the meeting.”","o":["are","was","is","has"],"k":"A","sk":"Makes subjects and verbs agree","b":"211–220","g":"GU"},{"n":31,"t":"mc","s":"Which word correctly completes the sentence?\n“The heavy rain had a big ___ on the harvest.”","o":["efect","affect","effect","afect"],"k":"C","sk":"Chooses between frequently confused words","b":"211–220","g":"GU"},{"n":32,"t":"mc","s":"Which word correctly completes the sentence?\n“The children have ___ all the juice.”","o":["drinked","drank","drunked","drunk"],"k":"D","sk":"Forms irregular past-tense and past-participle verbs","b":"211–220","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence is written correctly?","o":["The holy month of ramadan began last week.","The Holy Month of ramadan began last week.","The holy month of Ramadan began Last Week.","The holy month of Ramadan began last week."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"181–190","g":"ME"},{"n":34,"t":"mc","s":"Which sentence is written correctly?","o":["We met Mayor Fahd at the opening ceremony.","We met mayor Fahd at the opening ceremony.","We met Mayor Fahd at the Opening Ceremony.","We met Mayor fahd at the opening ceremony."],"k":"A","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"191–200","g":"ME"},{"n":35,"t":"mc","s":"Which sentence uses a comma correctly?","o":["The road, was icy so the drivers went slowly.","The road was icy, so the drivers went slowly.","The road was icy so the drivers, went slowly.","The road was icy so, the drivers went slowly."],"k":"B","sk":"Uses a comma before a conjunction in a compound sentence","b":"191–200","g":"ME"},{"n":36,"t":"mc","s":"Which sentence uses a comma correctly?","o":["When, the bell rang the students lined up.","When the bell rang the students, lined up.","When the bell rang, the students lined up.","When the bell, rang the students lined up."],"k":"C","sk":"Uses a comma after an introductory word, phrase or clause","b":"191–200","g":"ME"},{"n":37,"t":"mc","s":"Which word correctly completes the sentence?\n“The sky was ___ after the storm.”","o":["cloudlesss","clowdless","cloudles","cloudless"],"k":"D","sk":"Spells words with prefixes and suffixes correctly","b":"191–200","g":"ME"},{"n":38,"t":"mc","s":"Which book title is written correctly?","o":["The Secret of the Old Well","The secret of the old well","The Secret Of The Old Well","the Secret of the old Well"],"k":"A","sk":"Capitalizes and punctuates titles of works","b":"201–210","g":"ME"},{"n":39,"t":"mc","s":"Which word correctly completes the sentence?\n“The ___ of the story is to always tell the truth.”","o":["morale","moral","moralle","morrel"],"k":"B","sk":"Spells grade-level words correctly","b":"201–210","g":"ME"},{"n":40,"t":"mc","s":"Which sentence uses commas correctly?","o":["My family moved to Abha Saudi Arabia, in 2024.","My family moved to Abha, Saudi Arabia in, 2024.","My family moved to Abha, Saudi Arabia, in 2024.","My family moved, to Abha Saudi Arabia in 2024."],"k":"C","sk":"Uses commas in dates, addresses and letters","b":"211–220","g":"ME"},{"n":41,"t":"mc","s":"Which sentence is punctuated correctly?","o":["“Do you know,” asked Leen, “Where my book is?”","“Do you know,” asked Leen “where my book is?”","“Do you know,” asked Leen, “where my book is?”","“Do you know” asked Leen, “where my book is?”"],"k":"C","sk":"Punctuates dialogue and quotations","b":"211–220","g":"ME"},{"n":42,"t":"mc","s":"Which sentence uses apostrophes correctly?","o":["The boy’s’ coach checked everyone’s shoe’s.","The boys’ coach checked everyone’s shoes.","The boys’ coach checked everyones’ shoes.","The boys coach checked everyones shoes."],"k":"B","sk":"Uses apostrophes in contractions and possessives","b":"211–220","g":"ME"},{"n":43,"t":"mc","s":"Which word is spelled correctly?","o":["necessary","nessesary","neccessary","necesary"],"k":"A","sk":"Spells grade-level words correctly","b":"211–220","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]}]};
